window.MONSTER_CHUNK_104 = [{"name":"Shamira","cr":25,"xp":1638400,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar","fire"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["unholy aura (DC 31)"],"ac":42,"ac_touch":35,"ac_flat_footed":31,"ac_mods":"+4 deflection, +11 Dex, +7 natural, +10 profane","hp":553,"hd":"27d10+405","hdvalue":27,"hp_mods":["regeneration 15 (good)"],"fort":28,"ref":30,"will":26,"defensive_abilities":["fire shield","freedom of movement"],"dr":"15/ cold iron and good","immunities":["charm and compulsion effects","death effects","disease","fire","electricity","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30}],"sr":36,"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"2 claws +36 (1d8+9 plus 4d6 fire and burn), tail slap +31 (2d6+4 plus 4d6 fire, burn, and grab), 2 wings +31 (1d8+4 plus 4d6 fire and burn)","ranged":"firebow +43 (1d8+14/19-20/x3 plus 1d6 fire and burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"8d6 fire, DC 38"},{"type":"constrict","details":"2d6+13 plus 4d6 fire and burn"},{"type":"dream haunting"},{"type":"energy drain"},{"type":"fiery passion"},{"type":"profane benediction"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":35,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"fire shield","details":"warm shield only"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"mass suggestion"},{"spell":"telekinesis"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"meteor swarm"},{"spell":"nightmare"},{"spell":"summon demons"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"empowered delayed blast fireball"},{"spell":"quickened dominate person"},{"spell":"symbol of persuasion"}]}],"strength":29,"dexterity":32,"constitution":40,"intelligence":28,"wisdom":25,"charisma":37,"baseatk":27,"cmb":36,"cmb_special":"+4 vs. grapple","cmd":71,"feats":[{"feat":"Blinding Critical"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Deadly Aim"},{"feat":"Empower Spell-Like Ability (delayed blast fireball)"},{"feat":"Improved Critical (composite longbow)"},{"feat":"Improved Precise Shot"},{"feat":"Pinpoint Targeting"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Quicken Spell-Like Ability (dominate person)"},{"feat":"Rapid Shot"}],"skills":[{"skill":"Acrobatics","value":41},{"skill":"Bluff","value":51},{"skill":"Diplomacy","value":40},{"skill":"Disguise","value":43},{"skill":"Fly","value":49},{"skill":"Intimidate","value":40},{"skill":"Knowledge (planes, religion)","value":39},{"skill":"Perception","value":45},{"skill":"Perform (dance)","value":40},{"skill":"Sense Motive","value":37},{"skill":"Sleight of Hand","value":38},{"skill":"Spellcraft","value":36},{"skill":"Stealth","value":41},{"skill":"Use Magic Device","value":43}],"languages":["Abyssal","Celestial","Common","Draconic","Ignan","telepathy 300 ft."],"sq":[{"type":"change shape","details":"any humanoid; alter self"},{"type":"divine deception"},{"type":"nascent demon lord traits"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple","description_visual":"This crimson-haired demonic woman has wings of fire. She carries a slender bow made of flames.","source":"AP 76","special_abilities":[{"type":"Divine Deception","kind":"Su","details":"Once per day while Shamira uses her change shape ability, she can choose to emulate a different alignment for the purpose of divination spells that reveal auras (such as detect evil). This effect persists as long as she carries a holy symbol of a deity of the same alignment she wishes to emulate. This holy symbol must have been given to her within the previous hour by a worshiper of that deity; Shamira typically secures these symbols via mind control. This effect last for 2d6 hours, after which point the holy symbol crumbles to ashes. While it lasts, spells and other magical effects treat her alignment as if it were the feigned alignment, not her true alignment of chaotic evil. If she uses a symbol of Sarenrae to appear neutral good, this effect lasts for 24 hours before the symbol crumbles to dust."},{"type":"Dream Haunting","kind":"Su","details":"Shamira can use her energy drain attack, mind-affecting spell-like abilities, and profane benediction abilities on any creature she successfully affects with her nightmare spell-like ability while that ability is in effect. Once she uses one of these abilities against her target, the nightmare spell ends-she can only use one of these abilities per use of nightmare."},{"type":"Energy Drain","kind":"Su","details":"Shamira's energy drain ability functions like that of a succubus, except that it drains 2 levels per use. As a free action as part of this attack, she may choose use her burn special attack with her energy drain. With a successful DC 36 Will save, a character resists the suggestion implanted by this attack, and a successful DC 36 Fortitude save negates the negative level after 24 hours. The save DCs are Charisma-based."},{"type":"Fiery Passion","kind":"Su","details":"Shamira's passions and fires are one. A creature must be immune to both fire and mind-affecting effects in order to be immune to fire damage caused by Shamira. Creatures immune only to fire instead take fire damage as if they instead had fire resistance 10. Creatures with fire resistance and no immunity to mind-affecting effects take fire damage from Shamira's attacks as if they had no fire resistance."},{"type":"Firebow","kind":"Su","details":"As a swift action, Shamira can conjure a +5 flaming burst unholy composite longbow that creates arrows as she fires it. In addition, arrows fired from her firebow can inflict her burn special attack. Nascent Demon Lord Traits In addition to many of the defenses and abilities incorporated into Shamira's statistics above, her weapons (natural and manufactured) are treated as chaotic, epic, and evil for the purpose of resolving damage reduction. Also, she can grant spells to her worshipers-she grants access to the domains of Chaos, Charm, Evil, and Nobility and the subdomains of Demon, Leadership, Love, and Lust."},{"type":"Profane Benediction","kind":"Su","details":"This ability functions as the succubus's profane gift ability, except it grants a +4 profane bonus to an ability score of the target's choice rather than a +2 bonus. If the target is a worshiper of Sarenrae, the target also gains immunity to fire as long as the profane benediction persists, even if the worshiper at some point later abandons her faith in Sarenrae (as is often the case with those who are eager to keep their profane benedictions)."},{"type":"Summon Demons","kind":"Sp","details":"As a nascent demon lord, Shamira can summon any demon or combination of demons whose total combined CR is 20 or lower. This ability always works, and is equivalent to a 9th-level spell."}],"description":"Shamira, the Ardent Dream, is the nominal ruler of the isle of Alinythia, and by extension the city of Alushinyrra, but with the honor of ruling the largest of the Midnight Isles comes with an unwritten caveat-Nocticula's palace overlooks the city from its own isle. While this position is one that Shamira revels in, and one that has afforded her no small amount of inf luence (indeed, it's helped to propel her into the ranks of nascent demon lords), the Ardent Dream knows that her mistress watches over her always, and surely regards her not only as a valued lover, companion, and minion, but also as the closest thing Nocticula has to competition. Of course, Shamira does keep an eye out for any opportunity she has to erode some of Nocticula's power, for someday she hopes to wear Nocticula's crown.\n\nShamira is unique in her appearance. Even before she became a nascent demon lord, her burning wings and flowing crimson hair marked her as a succubus of power. Close-lipped about her history, she appeared in Nocticula's palace one moonrise and seduced the Lady in Shadow, thus earning the position of Lady of Alinythia. (Nocticula banished Shamira's predecessor, an incubus named Ziforian, to the sewers below the city, where he may yet lurk.) None in the Abyss recall this majestic and unmistakable succubus in the city before her arrival in Nocticula's boudoir. Shamira does little to quell rumors that her previous home was a much loftier place than the Abyss, and her resemblance to the deity Sarenrae provides endless speculation.","ecology":"","habitat_society":""},{"name":"Tarrasque","cr":25,"xp":1638400,"alignment":"N","size":"Colossal","type":"magical beast","init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"auras":["frightful presence (300 ft., DC 27)"],"ac":40,"ac_touch":5,"ac_flat_footed":37,"ac_mods":"+3 Dex, +35 natural, -8 size","hp":525,"hd":"30d10+360","hdvalue":30,"hp_mods":["regeneration 40"],"fort":31,"ref":22,"will":12,"dr":"15/epic","immunities":["ability damage","acid","bleed","disease","energy drain","fire","mind-affecting effects","paralysis","permanent wounds","petrification","poison","polymorph"],"sr":36,"speed":[{"type":"land","speed":40}],"melee":"bite +37 (4d8+15/15-20/x3 plus grab), 2 claws +37  (1d12+15), 2 gores +37 (1d10+15), tail slap +32 (3d8+7)","ranged":"6 spines +25 (2d10+15/x3)","space":"30 ft.","reach":"30 ft. (60 ft. with tail slap)","special_attacks":[{"type":"rush"},{"type":"spines"},{"type":"swallow whole","details":"6d6+22 plus 6d6 acid, AC 27, hp 52"}],"strength":41,"dexterity":16,"constitution":34,"intelligence":3,"wisdom":15,"charisma":14,"baseatk":30,"cmb":53,"cmb_special":"+4 vs. grapple","cmd":66,"feats":[{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Bleeding Critical"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+43 when jumping"},{"skill":"Perception","value":43}],"languages":["Aklo (cannot speak)"],"sq":[{"type":"carapace"},{"type":"powerful leaper"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This immense reptilian beast towers over the surroundings like a dinosaur, all teeth and horns and claws and thrashing spiked tail.","source":"PFRPG Bestiary","special_abilities":[{"type":"Carapace","kind":"Su","details":"The tarrasque's scales deflect cones, lines, rays, and magic missile spells, rendering the tarrasque immune to such effects. There is a 30% chance a deflected effect reflects back in full force at the caster; otherwise it is simply negated."},{"type":"Powerful Leaper","kind":"Ex","details":"The tarrasque uses its Strength to modify Acrobatics checks made to jump, and has a +24 racial bonus on Acrobatics checks made to jump."},{"type":"Regeneration","kind":"Ex","details":"No form of attack can suppress the tarrasque's regeneration-it regenerates even if disintegrated or slain by a death effect. If the tarrasque fails a save against an effect that would kill it instantly, it rises from death 3 rounds later with 1 hit point if no further damage is inflicted upon its remains. It can be banished or otherwise transported as a means to save a region, but the method to truly kill it has yet to be discovered."},{"type":"Rush","kind":"Ex","details":"Once per minute for 1 round, the tarrasque can move at a speed of 150 ft. This increases its Acrobatics bonus on checks made to jump to +87."},{"type":"Spines","kind":"Ex","details":"The tarrasque can loose a volley of six spear-like spines from its body as a standard action with a toss of its head or a lash of its tail. Make an attack roll for each spine-all targets must be within 30 ft. of each other. The spines have a range increment of 120 ft."}],"description":"The legendary tarrasque is among the world's most destructive monsters. Thankfully, it spends most of its time in a deep torpor in an unknown cavern in a remote corner of the world-yet when it wakens, kingdoms die.\n\nAlthough far from intelligent, the tarrasque is smart enough to understand a few words in Aklo (though it cannot speak). Likewise, it isn't mindless in its rampages, but instead focuses on targets that threaten it, and is difficult to distract with trickery.","ecology":"","habitat_society":""},{"name":"Tarrasque","cr":25,"xp":1638400,"alignment":"CE","size":"Colossal","type":"magical beast","subtypes":["spawn of Rovagug"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"auras":["frightful presence (300 ft., DC 27)"],"ac":40,"ac_touch":5,"ac_flat_footed":37,"ac_mods":"+3 Dex, +35 natural, -8 size","hp":525,"hd":"30d10+360","hdvalue":30,"hp_mods":["regeneration 40"],"fort":31,"ref":22,"will":12,"dr":"15/epic","immunities":["ability damage","ability drain","acid","bleed","disease","energy drain","fire","mind-affecting effects","paralysis","permanent wounds","petrification","poison","polymorph"],"sr":36,"speed":[{"type":"land","speed":40}],"melee":"bite +37 (4d8+15/15-20/x3 plus grab), 2 claws +37  (1d12+15), 2 gores +37 (1d10+15), tail slap +32 (3d8+7)","ranged":"6 spines +25 (2d10+15/x3)","space":"30 ft.","reach":"30 ft. (60 ft. with tail slap)","special_attacks":[{"type":"rush"},{"type":"spines"},{"type":"swallow whole","details":"6d6+22 plus 6d6 acid, AC 27, hp 52"}],"strength":41,"dexterity":16,"constitution":34,"intelligence":3,"wisdom":15,"charisma":14,"baseatk":30,"cmb":27,"cmd":42,"cmd_special":"+4 vs. disarm","feats":[{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Bleeding Critical"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+43 when jumping"},{"skill":"Perception","value":43}],"languages":["Aklo (can't speak)"],"sq":[{"type":"carapace"},{"type":"hibernation"},{"type":"powerful leaper"},{"type":"unstoppable force"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This immense reptilian beast towers over its surroundings, all teeth and horns and claws and thrashing spiked tail.","source":"Inner Sea Gods","special_abilities":[{"type":"Carapace","kind":"Su","details":"The tarrasque's scales deflect cones, lines, rays, and magic missile spells, rendering the tarrasque immune to such effects. There is a 30% chance a deflected effect reflects back in full force at the caster; otherwise it is simply negated."},{"type":"Powerful Leaper","kind":"Ex","details":"The tarrasque uses its Strength to modify Acrobatics checks made to jump, and has a +24 racial bonus on Acrobatics checks made to jump."},{"type":"Rush","kind":"Ex","details":"Once per minute, for 1 round, the tarrasque's speed increases to 150 ft., and its Acrobatics bonus on checks made to jump increases to +87."},{"type":"Spines","kind":"Ex","details":"The tarrasque can loose a volley of six spear-like spines from its body as a standard action with a toss of its head or a lash of its tail. Make an attack roll for each spine, all targets must be within 30 ft. of each other. The spines have a range increment of 120 ft."}],"description":"The Tarrasque, referred to in ancient texts as the \"Armageddon Engine,\" is the greatest of Rovagug's spawn. Its previously recorded devastation of Ninshabur and Avistan occurred in -632 AR, and culminated in the destruction of the flying Shory city of Kho. It was sealed away in a cavern somewhere in the Inner Sea region. Although the location of this cavern has been lost, rumors of possible locations include nearly every mountainous region, the Mwangi Expanse, and even under the Isle of Kortos itself.\n\nThe statistics presented here for the Tarrasque differ slightly from those in the Bestiary-this version more accurately represents the Tarrasque as the mightiest of Rovagug's spawn.","ecology":"","habitat_society":""},{"name":"Treerazer","cr":25,"xp":1638400,"alignment":"CE","size":"Huge","type":"outsider","subtypes":["demon","native"],"init":14,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["corruption (120 ft.)","unholy aura (DC 25)"],"ac":42,"ac_touch":22,"ac_flat_footed":32,"ac_mods":"+4 deflection, +10 Dex, +20 natural, -2 size","hp":574,"hd":"28d10+420","hdvalue":28,"hp_mods":["regeneration 15 (good)"],"fort":34,"ref":23,"will":10,"defensive_abilities":["freedom of movement"],"dr":"15/cold iron and good","immunities":["death effects","disease","electricity","mindaffecting effects","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":36,"speed":[{"type":"land","speed":60},{"type":"fly","speed":60,"maneuverability":"good"},{"type":"swim","speed":40}],"melee":"Blackaxe +44 (4d6+24/19-20/x3 plus 1d6  acid), bite +37 (2d6+6), 2 wings +37 (1d8+6)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"defoliation"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":35,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"},{"spell":"water breathing"}]},{"frequency":"at-will","spells":[{"spell":"antiplant shell"},{"spell":"contagion"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport","details":"within Tanglebriar only"},{"spell":"telekinesis"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"horrid wilting"},{"spell":"summon demons"},{"spell":"symbol of death"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"control plants"},{"spell":"quickened greater dispel magic"},{"spell":"wall of thorns"}]}],"strength":36,"dexterity":30,"constitution":40,"intelligence":21,"wisdom":24,"charisma":25,"baseatk":28,"cmb":15,"cmd":31,"cmd_special":"can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Flyby Attack"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (greataxe)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (greater dispel magic)"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":41},{"skill":"Fly","value":38},{"skill":"Intimidate","value":38},{"skill":"Knowledge (arcana)","value":36},{"skill":"Knowledge (nature)","value":36},{"skill":"Knowledge (planes)","value":36},{"skill":"Perception","value":38},{"skill":"Sense Motive","value":38},{"skill":"Spellcraft","value":33},{"skill":"Stealth","value":33},{"skill":"Swim","value":49}],"languages":["Abyssal","Common","Elven","Sylvan","telepathy 300 ft."],"sq":[{"type":"nascent demon lord traits"}],"environments":["any (Tanglebriar)"],"organizations":["solitary","group (Treerazer plus 1d4 nalfeshnees and 2d4 hezrous)"],"treasure":"triple (plus Blackaxe)","description_visual":"The twenty-foot-tall winged saurian demon wields an aciddripping axe. Two red eyes glow above a tooth-filled beak.","source":"Inner Sea World Guide","special_abilities":[{"type":"Aura of Corruption","kind":"Su","details":"Treerazer exudes an aura of corruption to a radius of 120 ft. This aura causes plants to grow hideous, sprouting thorns, twisting, and becoming fungoid in nature. Creatures with woodland stride or freedom of movement can move through this fungal bloom with ease. Living creatures within Treerazer's aura of corruption must make a DC 39 Fortitude save each round or their flesh grows pasty and clammy as tendrils of diseased plant matter and fungal growth sprout from it. This condition persists as long as the creature remains within Treerazer's aura of corruption and for 1 minute thereafter. While suffering the effects of this aura, the living creature is treated as a plant for the purposes of spells and effects that harm or otherwise inconvenience plant creatures more than other creatures. The victim would thus be subject to antiplant shell, blight, and additional damage from horrid wilting or a plant bane weapon, and could be affected by control plants. The corruption doesn't otherwise impart plant traits to creatures. The save DC is Constitution-based."},{"type":"Defoliation","kind":"Su","details":"As a standard action once every 1d4 rounds, Treerazer can exude a pulse of defoliating energy in a 30-foot-radius spread. This pulse appears as a wave of sickly green energy, and causes all plants and plant creatures in the area to blacken and wither. Such creatures take 20d10 points of damage and 1d8 points of Strength drain, or half with a successful DC 39 Fortitude save. A plant that isn't a creature (such as a tree or a shrub) doesn't receive a save and immediately withers and dies. Treerazer can choose to exclude any number of plants in the area from this effect, and generally does so to preserve twisted and corrupted plants and fungus. The save DC is Constitution-based. Nascent Demon Lord Traits A nascent demon lord is a powerful demon that has not yet made the full transition from unique demon to full demon lord of an Abyssal realm. Treerazer's current exile to the Material Plane prevents him from achieving full demon lord status. Yet he still possesses the typical nascent demon lord traits, which are similar to those possessed by a typical demon, only more potent, as summarized here. • Immunity to death effects, electricity, charm and compulsion effects, and poison. • Resistance to acid 30, cold 30, and fire 30. •."},{"type":"Summon","kind":"Sp","details":"Once per day, nascent demon lords can summon any demon or combination of demons whose total combined CR is 20 or lower. This ability always works, and is equivalent to a 9th-level spell. • Telepathy 300 ft. • A nascent demon lord's natural weapons, as well as any weapon it wields, are treated as chaotic, epic, and evil for the purpose of resolving damage reduction. • Nascent demon lords can grant spells to their worshipers. Granting spells doesn't require any specific action on the nascent demon lord's behalf. All nascent demon lords grant access to the domains of Chaos and Evil-in addition, they grant access to two other domains and a favored weapon that vary according to the nascent demon lord's themes and interests."}],"description":"Treerazer, the self-styled Lord of the Blasted Tarn, was once the favored minion and lieutenant (some even say child) of Cyth-V'sug, Demon Lord of Fungus and Parasites. After a failed attempt to wrest that crown away from Cyth-V'sug, Treerazer fled to the Material Plane. Cyth-V'sug was unable (or perhaps only unwilling) to pursue, but took steps to ensure that Treerazer would remain there by exiling him, transforming Treerazer into a native outsider and severing his bond to the Abyss-if the Lord of the Blasted Tarn is slain, his animus will not return to the Abyss and reform.\n\nDeath, to Treerazer, is a permanent thing.\n\nTreerazer arrived on Golarion near the end of the Age of Darkness, and found the savaged planet much to his liking-so much so that the sting of exile was somewhat ameliorated. He spent many centuries wandering the remote corners of Golarion before finally coming upon the abandoned elven nation of Kyonin in 2497 ar. In the Sovyrian Stone, he found an artifact that he believed he could use to reinstate his Abyssal link and, perhaps, even uproot the entire nation and refocus the portal from Sovyrian to the Abyss, thereby reclaiming his position there and taking one more step toward revenge against Cyth-V'sug.\n\nYet the elves sensed his tamperings and returned to confront the demon. A terrific battle resulted, and while the elves were able to drive Treerazer out of Iadara and into southern Kyonin, they were unable to slay him or force him out completely-they merely concentrated his power in a smaller region. Instead, the elves \"walled off \" this region, a perverted realm known today as the Tanglebriar. Treerazer lurks at the Tanglebriar's heart to this day, the greatest bogeyman in elven mythology and a very real and constant threat to the nation's security.\n\nTreerazer begins most combats by casting time stop and raising an antiplant shell to prevent plant creatures (including creatures under the effect of his aura of corruption) from approaching. If he has time, he also creates walls of thorns and summons demons (usually four nalfeshnees and 12 hezrous). In melee, Treerazer gleefully takes up Blackaxe and makes full attacks against the closest foe, or Greater Vital Strikes if he's forced to move or charge. During the first 3 rounds of combat, he targets obvious spell effects with quickened greater dispel magic. If Treerazer is reduced to fewer than 150 hit points, he teleports back to his fortress, Witchbole, to recover and plan his revenge.\n\nTreerazer's Cult Cults of Treerazer are quite rare beyond Kyonin, where secret cabals of cultists venerate him. When they do appear beyond these borders, they are secretive but sadistic groups, eager to sacrifice nonbelievers yet cunning in remaining undetected by the law of the land. Treerazer's symbol is a bleeding dead tree that's been split in half. His clerics have access to the Domains of Chaos, Destruction, Evil, and Plant. His favored weapon is the battleaxe.","ecology":"","habitat_society":"","gear":"Blackaxe"},{"name":"Bezravnis","cr":26,"xp":2457600,"alignment":"CN","size":"Colossal","type":"magical beast","subtypes":["earth","kaiju"],"init":9,"senses":[{"type":"darkvision","modifier":"600 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"600 ft."}],"ac":44,"ac_touch":7,"ac_flat_footed":39,"ac_mods":"+5 Dex, +37 natural, -8 size","hp":615,"hd":"30d10+450","hdvalue":30,"hp_mods":["fast healing 30"],"fort":32,"ref":24,"will":20,"defensive_abilities":["ferocity","recovery"],"dr":"20/epic","immunities":["ability damage","ability drain","death effects","disease","energy drain","fear","fire"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"electricity","value":30},{"type":"negative energy","value":30},{"type":"sonic","value":30}],"speed":[{"type":"land","speed":100},{"type":"burrow","speed":100}],"melee":"2 claws +40 (4d6+18/19-20 plus grab), 3 stings +40 (3d6+18/19-20 plus 2d6 fire and poison)","space":"50 ft.","reach":"50 ft.","special_attacks":[{"type":"burrowing charge"},{"type":"constrict","details":"4d6+27"},{"type":"heat beam"},{"type":"hurl foe"},{"type":"poison"},{"type":"trample","details":"2d8+27, DC 43"},{"type":"web","details":"+27 ranged, DC 40, 30 hp"}],"strength":47,"dexterity":20,"constitution":40,"intelligence":3,"wisdom":26,"charisma":23,"baseatk":30,"cmb":56,"cmb_special":"+4 vs. bull rush, +4 vs. grapple","cmd":71,"cmd_special":"+2 vs. bull rush, +12 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (sting)"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":31},{"skill":"Perception","value":37},{"skill":"Stealth","value":2,"special":"+32 when burrowing"}],"languages":["Terran (can't speak)"],"sq":[{"type":"massive"},{"type":"no breath"}],"environments":["warm deserts"],"organizations":["solitary (unique)"],"treasure":"incidental","description_visual":"The armored plates of this immense, three-tailed scorpion are fiery red, and its stingers glow with molten heat.","group":"Kaiju","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Burrowing Charge","kind":"Ex","details":"Once per minute, Bezravnis can make a charge attack while burrowing through loose earth, sand, mud, or magma, or through any other loosely packed earth or stone. When Bezaravnis reaches the target, it erupts from the ground as part of its attack. If Bezravnis hits the target of its burrowing charge attack, it deals double damage with its attack. Any creatures standing in or flying less than 50 ft. above the space Bezravnis occupies at the end of this charge are immediately subjected to Bezravnis's trample attack. Any buildings entirely within this space take double damage from the trample attack (4d8+54 points)-this damage bypasses hardness. In addition, Huge or smaller creatures must succeed at a DC 40 Reflex save or be buried in earth, as if by a cave-in or collapse. This bury zone extends into all squares affected by Bezravnis's reach."},{"type":"Heat Beam","kind":"Su","details":"Once every 4 rounds, Bezravnis can fire beams of searing heat and fire from one of its three stingers. Each stinger's heat beam is a separate attack with its own 4-round recharge period. The kaiju may fire one heat beam from a stinger as a move action, two heat beams as a standard action, or all three as a full-round action. Each heat beam is a 1,200-foot-long line that deals 20d6 points of fire damage to everything in its path (Reflex DC 40 half). If Bezravnis fires more than one heat beam, it can direct them in different directions. The save DC is Constitution-based."},{"type":"Poison","kind":"Su","details":"Sting-injury; save Fort DC 40; frequency 1/round for 6 rounds; effect staggered for 1 round plus loss of fire immunity and resistance; cure 3 consecutive saves. As long as a creature suffers the effects of Bezravnis's poison, it loses all racial resistances and immunities to fire. Any spell or spell-like effects active when the target fails its initial saving throw against this poison are suppressed as long as it continues to be staggered by the poison. New effects of this nature that become active after that initial failed saving throw function normally if the caster succeeds at a DC 35 caster level check; otherwise, the spell effects are suppressed until the victim is no longer staggered."},{"type":"Web","kind":"Ex","details":"Bezravnis's webs are immune to fire damage. In addition, these webs are semi-living things that continue to crush and squeeze those entangled by them. If a creature is entangled in the webs, at the start of each turn during which it is entangled, it takes 2d6+6 points of bludgeoning damage as the webs crush and constrict it. This ability otherwise functions the same as the universal monster ability."}],"description":"Bezravnis, known also as the Inferno Below, dwells in the sands of a sparsely inhabited high-altitude desert found in the shadow of the world's largest mountain range. There, the 130-foot-long beast slumbers the centuries away until its cycle of wakefulness rouses it from its torpor and causes it to emerge from the sands in an eruption of fire and ash. The Inferno Below then begins its rampage, traveling in a straight line toward a heavily populated region bordering the great desert. Typically, the Inferno Below's rampage is limited to a single city, and never the same one twice in a row. After destroying no less than two-thirds of the city, it retreats back to the vast desert, burrows deep, and settles into a new sleep of ages. The reason for the Inferno Below's cyclic rampages isn't well understood, but the cycle of these rampages functions like clockwork-they take place every 273 years with little deviation. As there seems to be no pattern to the kaiju's attacks themselves, with a different city being targeted each cycle, the cities of the bordering nations do their best to prepare for the monster's attack. The nations themselves have little love for each other, and attempts to generate lures to direct the kaiju's march toward an enemy city are common-yet these lures have yet to work, and in fact they seem to result in the kaiju attacking a city in the luring nation more often than not. Other cities spare no expense during a so-called \"Inferno Season,\" and send huge armies of scouts into the desert to watch for signs of the kaiju's emergence or traces of its burrowing passage through the sands, in hopes of determining the direction of the beast's travel and warning likely target cities (or, in the case of a trajectory that leads it to an enemy city, working to silence warnings). Kaiju scholars have correlated Bezravnis's appearance with the passage of a singular red comet in the skies above the world-an astronomical event known as the Inferno Star. As the comet nears the world, Bezravnis emerges, and as the comet vanishes from the sky, the kaiju turns its back and returns to the desert. Confirmation of this correlation has given rise to numerous theories. Some believe that Bezravnis first fell to the world from the Inferno Star, and its advent wakens within the beast a bewildered longing for home that drives it into a frenzy. Others hold that the kaiju exists as a guardian against an even more deadly occupant of the Inferno Star, and that by displaying its power by destroying a city, Bezravnis is in fact protecting the world by driving the Inferno Star back into the depths of space.\n\nBut Bezravnis doesn't always have the luxury of waiting for the Inferno Star to draw near before waking. At several points in the past, lunatics, cults, and accidents have woken the kaiju before its appointed time. Some mad, apocalyptic-minded spellcasters use powerful magic to cause great explosions above the sands where the kaiju slumbers. Earthquakes, severe weather phenomena, and similar natural events have been known to waken the monster early as well. When Bezravnis wakens off-cycle like this, the monster is particularly foul-tempered. It's rampage doesn't follow a straight line-instead, its travels are erratic as it pursues the perceived cause of its wakening with single-minded ferocity and tenacity. In this way, cults have accomplished what the border nations have not-leading the kaiju to attack an enemy. Of course, such tactics are dangerous and often backfire, for Bezravnis is fast and destructive, and it has been known to follow such tormenters. Bezravnis doesn't seem to be particularly vexed by the presence of other kaiju, and ignores them unless it is attacked first. Once attacked, however, the Inferno Below becomes singularly focused and deviates from its path to fight the target creature as long as it remains visible or alive. Smaller foes can sometimes distract the kaiju from its path in this manner if they can deal enough damage upon the creature to bait it into directing its furious rage on them.","ecology":"","habitat_society":""},{"name":"Korada","cr":26,"xp":2457600,"alignment":"NG","size":"Large","type":"outsider","subtypes":["agathion","extraplanar","good"],"init":22,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"detect thoughts"},{"type":"low-light vision"}],"auras":["primal (30 ft.)"],"ac":45,"ac_touch":40,"ac_flat_footed":36,"ac_mods":"+10 Dex, +1 dodge, +2 insight, +13 natural, -1 size, +6 sacred, +12 Wis | never flat-footed","hp":528,"hd":"32d10+352","hdvalue":32,"hp_mods":["regeneration 10 (evil artifacts, effects, and spells)"],"fort":21,"ref":30,"will":30,"defensive_abilities":["never surprised"],"dr":"10/epic and evil","immunities":["ability damage","ability drain","charm effects","compulsion effects","death effects","disease","electricity","energy drain","petrification","poison"],"resists":[{"type":"cold","value":30},{"type":"sonic","value":30}],"sr":37,"speed":[{"type":"land","speed":90},{"type":"climb","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"unarmed strike +36 (2d10+8) or +5 quarterstaff +44 (1d8+13) or flurry of blows +38 (2d10+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"shatter spells"},{"type":"stunning fist","details":"8/day, DC 22"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":31,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect thoughts"},{"spell":"foresight"},{"spell":"sanctuary"},{"spell":"water walk"}]},{"frequency":"at-will","spells":[{"spell":"augury"},{"spell":"bless"},{"spell":"calm animals"},{"spell":"calm emotions"},{"spell":"cure serious wounds"},{"spell":"greater teleport"},{"spell":"mirror image"}]},{"frequency":"1/day","spells":[{"spell":"antimagic field"},{"spell":"moment of prescience"}]},{"frequency":"3/day","spells":[{"spell":"divination"},{"spell":"mad monkeys"},{"spell":"neutralize poison"},{"spell":"quickened mirror image"},{"spell":"true seeing"},{"spell":"wall of force"}]}],"strength":26,"dexterity":30,"constitution":33,"intelligence":25,"wisdom":35,"charisma":38,"baseatk":32,"cmb":41,"cmb_special":"+2 vs. disarm or grapple, +4 vs. trip","cmd":84,"cmd_special":"+2 vs. disarm, grapple, or trip","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Greater Trip"},{"feat":"Improved Disarm"},{"feat":"Improved Grapple"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"},{"feat":"Improved Unarmed Strike","type":"bonus"},{"feat":"Lunge"},{"feat":"Mobility"},{"feat":"Quicken Spell-Like Ability (mirror image)"},{"feat":"Scorpion Style"},{"feat":"Snatch Arrows"},{"feat":"Spring Attack"},{"feat":"Step Up"},{"feat":"Stunning Fist","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":44,"special":"+68 when jumping"},{"skill":"Bluff","value":32},{"skill":"Climb","value":50},{"skill":"Diplomacy","value":45},{"skill":"Disguise","value":32},{"skill":"Escape Artist","value":26},{"skill":"Fly","value":8},{"skill":"Heal","value":27},{"skill":"Knowledge (arcana, geography, history, nature)","value":23},{"skill":"Knowledge (local)","value":22},{"skill":"Knowledge (planes, religion)","value":41},{"skill":"Perception","value":46},{"skill":"Sense Motive","value":46},{"skill":"Spellcraft","value":22},{"skill":"Stealth","value":40}],"languages":["Celestial","Infernal","speak with animals","truespeech"],"sq":[{"type":"abundant step"},{"type":"change shape","details":"avoral or any humanoid, shapechange"},{"type":"combat style master"},{"type":"empyreal lord traits"},{"type":"ki pool","details":"22 points; adamantine, epic, good, lawful, magic, mythic, silver"},{"type":"lay on hands","details":"15d6, 29/day"},{"type":"seed of life"},{"type":"tranquil master"}],"environments":["any forests (Nirvana)","any mountains (Nirvana)"],"organizations":["unique"],"treasure":"standard (+5 quarterstaff)","description_visual":"This serene, acrobatic man has stiff sideburns, a beard like a monkey, and three golden-furred tails.","group":"Empyreal Lord","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Combat Style Master","kind":"Ex","details":"Korada can attack with unarmed strikes and perform flurry of blows as a 20th-level monk. Like a monk, he adds his Wisdom bonus to his AC and CMD. As a swift action, Korada may enter the basic stance of any combat style feat (such as Crane StyleUC, Monkey StyleUC, and so on) as if he had the first feat in the feat path for that combat style. By expending 2 points of ki, he may use any two feats from his current combat style's feat path for the next minute; if he changes his stance, the previous stance's feats become unavailable but he may use feats from the new stance."},{"type":"Primal Aura","kind":"Su","details":"Korada's primal aura radiates calm and tranquility, automatically suppressing any non-mythic charm or compulsion effect on any creature within its area. Any creature in his aura (including him) can deal nonlethal damage with weapons without taking the -4 penalty on attack rolls for doing so."},{"type":"Shatter Spells","kind":"Su","details":"Korada can destroy a magical effect (whether it's on a creature or an independent effect such as a wall of fire) by attacking it with an unarmed strike. He must succeed at a melee touch attack against the creature or effect and expend 2 points of ki. If the attack hits, the creature or effect is subject to targeted greater dispel magic (CL 20th). If he dispels an effect, he suffer no harmful effects from touching it. If the effect is on a creature, the creature takes 1 point of damage per spell level of each effect dispelled."},{"type":"Tranquil Master","kind":"Su","details":"Korada may attack without breaking his sanctuary spell-like ability so long as he only attempts to deal nonlethal damage."}],"description":"Korada is the champion of peace, kindness, and forgiveness. While he loves and respects his fellow empyreal lords for their tireless fight against wickedness, Korada believes good's final triumph will come from the redemption of evil creatures rather than their destruction. Honest, joyful, and clever, the Open Hand of Harmony dispenses wisdom with warmth and humility, and freely shares the secrets he has amassed over ages of study and meditation. Korada's dedication to philosophy and introspection have garnered him the ability to read the diverse threads of the world, see their nearly limitless connections, and then act on them with uncanny foresight. With neither the na&#239;vety of youth nor the jaded weariness of age, Korada is a perfect balance of sentient intelligence and animal instinct, at home wherever he is. Though he can assume many forms, Korada's true appearance is a slender, athletic man wearing a simple monk's robe. He has a golden monkey-like beard and sideburns, three monkey tails, and a light layer of downy golden fur covering the rest of his body. On Nirvana, Korada dwells in the Dream Lotus, a serene palace city whose blossoming violet walls always drip with cool, golden nectar that is said to calm even the wildest of spirits. It's a place of refuge and healing, and no violence is allowed within its walls; those with problems controlling their anger are sent to meditate at one of its many calming sacred pools. Korada is said to possess the gift of foresight, but he rarely acts on these strange visions. He believes the struggle to change is always worthwhile, even if such a journey doesn't always end in success. It's the process, not the result, that matters most to Korada. Despite his staunch dedication to peace, Korada's skill in battle is respected, and he's able to utilize almost any fighting style without a second's pause. He may be responsible for inspiring or teaching the animal combat styles to mortals, using various guises over the course of history on many worlds-or he may even have persuaded the creator gods to give the animals their instincts and talents for fighting, which led to mortals studying and emulating animal combat styles. Korada's reputation for peace and martial skill earned him the role of the diplomat of the empyreal lords and their celestial armies. Balor lords, demodand warlords, and even infernal dukes have (temporarily) abandoned their dreams of conquest and warmongering when the Open Hand of Harmony has arrived-alone-in their court to suggest that they consider a different path. These visits always leave behind a path of dazed and stunned fiends, surprised and awed by how easily he defeated them; most silently suffer this indignation and plan vengeance for the next time he appears. Although Korada is usually serene and gentle, he has a mischievous side and has been known to poke fun at or harass his opponents like a capricious monkey. He combines his skill in battle and gift for trickery to lead dangerous opponents away from innocents or into places where they can more easily be captured or subdued. That said, Korada abhors violence, and he prefers to make nonlethal attacks (using his primal aura and tranquil master abilities), disabling foes so he can speak to them of their weakness. He dispatches mindless opponents without hesitation, not wanting to waste energy debating or persuading a thing empty of thoughts and incapable of making moral choices. He challenges enemy leaders to single combat if doing so would prevent violence between other combatants.\n\nKORADA'S FAITH Korada is worshiped by good fey, awakened animals, and mortal clerics and monks seeking inner peace. Many who have lived with constant violence pray to Korada for guidance in finding balance; others are inspired by his light heart and willingness to confront wickedness with compassion and humor. Many who worship him are once-evil creatures who chose the path of redemption, as well as paladins who strayed and are working to stay true to the path of righteousness and mercy. The empyreal lord's sacred places are diplomatic embassies, mountain monasteries, and wells. Korada's holy symbol is two devotees kneeling before a lotus or a golden monkey with three tails. His favored weapon is the unarmed strike. His clerics have access to the domains of Good, Healing, Magic, and Protection, and the subdomains of Agathion, Defense, Divine, and Restoration.","ecology":"","habitat_society":""},{"name":"Kostchtchie","cr":26,"xp":819200,"alignment":"CE","size":"Huge","type":"outsider","subtypes":["chaotic","cold","demon","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["frightful presence (120 ft., DC 33)","unholy aura (DC 26)"],"ac":44,"ac_touch":30,"ac_flat_footed":38,"ac_mods":"+4 deflection, +6 Dex, +14 natural, +12 profane, -2 size","hp":604,"hd":"31d10+434","hdvalue":31,"hp_mods":["regeneration 30 (deific or mythic)"],"fort":35,"ref":20,"will":31,"defensive_abilities":["Abyssal resurrection","freedom of movement","rock catching"],"dr":"20/cold iron, epic, and good","immunities":["ability damage","ability drain","charm effects","compulsion effects","cold","death effects","electricity","energy drain","petrification","and poison"],"resists":[{"type":"acid","value":30},{"type":"fire","value":30}],"sr":37,"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":60},{"type":"climb","speed":60}],"melee":"+5 adamantine icy burst warhammer +53 (3d6+24/19-20/x3 plus 1d6 cold), slam +48 (1d8+19 plus grab)","ranged":"rock +37 (2d6+19)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"clutch foe"},{"type":"crushing blow"},{"type":"favored enemy","details":"giants +4, humans +4, see below"},{"type":"powerful slam"},{"type":"rock throwing","details":"600 ft."},{"type":"vengeful strike"}],"spell_like_abilities_caster_level":26,"spell_like_abilities_concentration":40,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"cone of cold"},{"spell":"desecrate"},{"spell":"enlarge person"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"mass icy prison"},{"spell":"polar midnight"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"polar ray"},{"spell":"power word stun"},{"spell":"summon demons"},{"spell":"symbol of stunning"}]}],"strength":48,"dexterity":23,"constitution":38,"intelligence":25,"wisdom":30,"charisma":27,"baseatk":31,"cmb":52,"cmb_special":"+2 vs. bull rush, +4 vs. grapple, +4 vs. sunder","cmd":86,"cmd_special":"+2 vs. bull rush, +2 vs. sunder","feats":[{"feat":"Awesome Blow"},{"feat":"Catch Off-Guard"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Greater Sunder"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (warhammer)"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Quick Draw"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":42},{"skill":"Climb","value":58},{"skill":"Intimidate","value":42},{"skill":"Knowledge (arcana)","value":41},{"skill":"Knowledge (engineering)","value":38},{"skill":"Knowledge (local)","value":41},{"skill":"Knowledge (planes)","value":41},{"skill":"Knowledge (religion)","value":38},{"skill":"Perception","value":52},{"skill":"Sense Motive","value":44},{"skill":"Spellcraft","value":41},{"skill":"Stealth","value":32},{"skill":"Use Magic Device","value":39}],"languages":["Abyssal","Celestial","Common","Draconic","Giant","telepathy 300 ft."],"sq":[{"type":"demon lord traits"}],"environments":["any cold (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (+5 adamantine icy burst warhammer)","description_visual":"This towering giant with twisted legs has human skulls woven into his beard and holds an immense warhammer.","group":"Demon Lord","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Clutch Foe","kind":"Ex","details":"If Kostchtchie chooses to use his hand to make a grapple check when he successfully slams and grabs a Medium or smaller opponent, he takes a -20 penalty on the grapple check. On following rounds, he can attempt to maintain his grapple on the creature as a swift action. If successful, he can constrict the creature for 1d8+28 points of damage, throw the creature (treat this as a bull rush), or use the creature as an improvised weapon. An opponent used as a weapon takes half as much damage as it deals to the creature it hits."},{"type":"Crushing Blow","kind":"Su","details":"Once per round, Kostchtchie may designate any attack with his warhammer to be a crushing blow. He must designate this attack before making the attack roll. If he hits, the blow ignores the target's hardness and damage reduction, and allows him to make a free trip attempt against the target. This trip attempt doesn't provoke an attack of opportunity, can target a foe of any size, and has no chance of causing Kostchtchie to fall prone if he fails. A creature struck by a crushing blow must attempt a DC 44 Fortitude save; success means the creature is staggered for 1 round, and failure means it is stunned for 1 round and staggered for 1d6 rounds afterward. The save DC is Strength-based."},{"type":"Favored Enemy","kind":"Su","details":"Against female giants or female humans, Kostchtchie's favored enemy bonuses increase to +8. Once per day, he can declare any one creature as a favored enemy, but only if that creature has damaged, humiliated, or otherwise inconvenienced him at some point in the previous 24 hours. His favored enemy bonuses against that creature last 24 hours."},{"type":"Powerful Slam","kind":"Ex","details":"Kostchtchie's slam attack is considered a primary attack even when he uses a weapon in his other hand, and he always adds his full Strength bonus to damage dealt with his slam attack."},{"type":"Vengeful Strike","kind":"Su","details":"Once per round, Kostchtchie may make an attack of opportunity against any creature that strikes him in melee combat. This attack of opportunity has a critical threat range of 18-20. Against female targets, the vengeful strike is also a crushing blow."}],"description":"Kostchtchie (pronounced kosh-TIK-ti-kai) appears as an immense, deformed frost giant with twisted legs, tiny white eyes, and a thick matted beard into which are woven dozens of skulls-trophies of mortal kings and priests of rival faiths he has slain. Legends speak that each of these skulls is haunted by the ghost of its previous owner, and that he can commune with these spirits to seek their wisdom-although if the legends are true, it is more likely that Kostchtchie has little interest in anything but mockery and torment for these lost souls. Kostchtchie is never seen without his massive warhammer, an adamantine maul of such prodigious size that even the strongest frost giant would have trouble wielding it properly. Known also as the Deathless Frost, Kostchtchie dwells in an immense Abyssal fortress carved from the heart of a towering mountain in a frozen realm of jagged mountains and immense glaciers infested with manifold frozen horrors. Kostchtchie stands 30 ft. tall. Kostchtchie was born of human parents, and became a murderer when his father forced him to kill his mother and sisters. Kostchtchie went one better and murdered his father as well. Later in life, after he had become a ferocious warlord well known for the slaying of dozens of giant chieftains, he confronted the Witch Queen Baba Yaga and tried to force her to grant him immortality-she agreed, but twisted his form, turned him into a hideous giant, and hid away the last fragment of his mortal soul in a magical torc. Kostchtchie fled to the Abyss to nurture his hatred and hide his shame, eventually finding a new purpose as a patron of frost giants despite his hatred of their kind. Kostchtchie longs for the recovery of the torc that contains the fragment of his soul, in the hope that its return might reverse his deformity without removing his immortality. In combat, Kostchtchie almost always uses Power Attack, taking a -8 penalty on all attack rolls but gaining a +16 bonus on damage rolls. The Deathless Frost is often accompanied by several frost giants, at least two of which are clerics. These clerics attend his every need, healing him in battle as best they can lest they forfeit their lives-or fall to some fate even more dire at the merciless hands of the Deathless Frost.\n\nKOSTCHTCHIE'S CULT\n\nKostchtchie is worshiped by giants-primarily frost giants, although many ettins, hill giants, and ogres worship him as well. Some white dragons worship the Deathless Frost, and even certain barbaric human tribes in the frozen reaches of the world have been known to venerate him. He doesn't tolerate women in his cults, and never grants female clerics spells. He is served by half-fiend yetis, ice linnorms, remorhazes, and other cold-dwelling monsters of great size. Kostchtchie's unholy symbol is an ice-caked, rune-carved warhammer, and the warhammer is his favored weapon. He grants access to the domains of Chaos, Evil, Strength, and War, and access to the subdomains of Demon, Ferocity, Ice, and Tactics (although the Ice subdomain is normally not available without the Water domain, an exception is made in this case because of the demon lord's close association with cold).","ecology":"","habitat_society":""},{"name":"Agyra","cr":27,"xp":3276800,"alignment":"CN","size":"Colossal","type":"magical beast","subtypes":["air","kaiju"],"init":11,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"600 ft."},{"type":"low-light vision"}],"ac":45,"ac_touch":9,"ac_flat_footed":38,"ac_mods":"+7 Dex, +36 natural, -8 size","hp":656,"hd":"32d10+480","hdvalue":32,"hp_mods":["fast healing 30"],"fort":33,"ref":25,"will":21,"defensive_abilities":["electrified corpse","ferocity","rebirth","recovery"],"dr":"20/epic","immunities":["ability damage","ability drain","death effects","disease","electricity","energy drain","fear"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30},{"type":"negative energy","value":30},{"type":"sonic","value":30}],"speed":[{"type":"land","speed":80},{"type":"fly","speed":200,"maneuverability":"average"}],"speed_mod":"swift flight","melee":"2 bites +41 (6d6+17/19-20), 2 talons +41 (3d8+17), tail slap +36 (10d6+8/19-20 plus bleed)","space":"50 ft.","reach":"50 ft. (75 ft. with tail)","special_attacks":[{"type":"bleed","details":"5d6"},{"type":"blinding flash"},{"type":"breath weapon"},{"type":"hurl foe"},{"type":"hurricane"},{"type":"thunderous blast"}],"strength":44,"dexterity":25,"constitution":41,"intelligence":3,"wisdom":29,"charisma":25,"baseatk":32,"cmb":57,"cmb_special":"+4 vs. bull rush","cmd":74,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Vital Strike"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (tail slap)"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"},{"feat":"Wingover"}],"skills":[{"skill":"Fly","value":24},{"skill":"Perception","value":38}],"languages":["Auran (can't speak)"],"sq":[{"type":"massive"},{"type":"storm flier"}],"environments":["warm mountains"],"organizations":["solitary (unique)"],"treasure":"incidental","description_visual":"This two-headed monstrosity has vast wings and a long tail covered in a forest of blades.","group":"Kaiju","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Blinding Flash","kind":"Su","details":"By spreading her wings as a full-round action while she stands upon the ground, Agyra can create a blinding flash of light that targets all creatures within 100 ft. Affected creatures must succeed at a DC 41 Fortitude save or be permanently blinded and staggered for 1d6 rounds by the blast of light. A successful saving throw reduces the blindness to 1 round and negates the staggered effect. The save DC is Constitution-based."},{"type":"Breath Weapon","kind":"Su","details":"Once every 4 rounds as a standard action, each of Agyra's twin heads can breathe out a line of electricity to a range of 1,200 ft. Agyra can breathe each line in a different direction. Each creature caught in a line of electricity must succeed at a DC 41 Reflex save or take 20d6 points of electricity damage and be staggered for 1d4 rounds. A successful saving throw halves the damage and negates the staggered effect. A creature struck by both breath weapons simultaneously must attempt separate saving throws against each breath weapon, but takes a -4 penalty on both-the damage and staggered condition duration stack with each other. A creature wearing medium or heavy metal armor or a creature composed mostly of metal that fails its saving throw is also stunned for 1 round. A creature slain by Agyra's breath weapon remains electrified for 2d4 rounds after death-any creature that touches the body automatically takes 3d6 points of electricity damage. The save DC is Constitution-based."},{"type":"Electrified Corpse","kind":"Su","details":"If Agyra is slain, her corpse crackles and flashes with pulses of electrical light if she has not used her rebirth ability that year. Any creature that touches her corpse takes 3d6 points of electricity damage. Even if Agyra's body is destroyed, the site of her death continues to carry this electrical charge for 1 minute, or until Agyra is reborn, whichever comes first."},{"type":"Hurricane","kind":"Sp","details":"Once per day, Agyra can create a supernatural hurricane surrounding herself. This effect functions as control weather, save that it affects an area with a 4-mile radius, lasts for 24 hours, and can only be used to create hurricane-force winds. The hurricane created is static, and features a calm eye at the center with a 500-foot radius."},{"type":"Rebirth","kind":"Su","details":"Agyra remains dead for only 1 minute before she come back to life, as if via a true resurrection spell. Agyra rises from the exact same position she occupied when she died, and typically takes advantage of this second chance to use her swift flight to escape as soon as possible. Agyra can only be reborn in this manner once per year; if she is slain a second time before a year has passed, her death is permanent and her corpse doesn't become electrified. This ability replaces Agyra's ability to immediately heal damage that would normally kill her, granted by her recovery ability, but doesn't replace the other defenses granted by recovery."},{"type":"Storm Flier","kind":"Ex","details":"Agyra doesn't take penalties on Fly checks when flying in strong or more powerful winds."},{"type":"Swift Flight","kind":"Su","details":"As a standard action once per hour, Agyra can fly in a straight line at an incredible speed. She may travel up to 1 mile in this manner-doing so doesn't provoke attacks of opportunity. When Agyra activates this ability, her thunderous blast ability is automatically triggered from the swift flight's point of origin."},{"type":"Thunderous Blast","kind":"Su","details":"When Agyra uses her swift flight, she creates a thunderous sonic boom. This devastating explosion of sound occurs at her location when she activates swift flight, filling an area equal to her space and her reach combined-resulting in a 100-foot-diameter burst of sonic energy. All creatures in this area of effect take 20d10 points of sonic damage, are permanently deafened, are knocked prone, and are stunned for 1 round. A successful DC 41 Reflex save halves the damage, reduces the deafened condition to 1d4 rounds, and negates the knocked prone and stun effects entirely. The save DC is Constitution-based."}],"description":"Agyra, the Forever Storm, is believed by many cultures to be the cause of seasonal typhoons or other great storms—such tempests being a manifestation of Agyra's monstrous breaths as she exhales during her long slumber every season. While this kaiju isn't in fact responsible for the world's storms, her powers over wind and lightning are significant, and when she is vexed to rampage, the effects of her hurricanes can be as devastating to a region as her more direct attacks. Agyra has the appearance of a primeval, two-headed flying reptile with a wingspan of over 150 ft. Her tail is perhaps the most fearsome of her aspects. This lengthy and flailing appendage is covered with razor-sharp blades and wickedly barbed spines capable of slashing through buildings and tearing through armor with great force and from great distances. Agyra dwells on the upper slopes of a long-dormant volcano that sits on a remote tropical island beyond the main shipping lanes and the scope of most explorers' travels. As with many kaiju, she spends the bulk of her time in deep and peaceful slumber. She is ferociously protective of the strange peoples who dwell on the shores of this island, and has been known to rouse herself to come to their defense against slavers, pirates, or other external threats to their way of life. Despite this strange protective streak, Agyra isn't a kindly creature-and none know this more plainly than those who share her island. Her responses to intrusions to the island may simply be defenses of her perceived territories, for certainly the villages of the locals suffer significant damage during her local rampages. She's been known to take wing to travel to distant cities as well, often as a result of some of her island's inhabitants being taken from the shores as slaves. Yet the devastation she wreaks upon the slavers' destination cities pays no regard to the safety of the slaves themselves-they are in as much danger as anyone else from the kaiju's vengeful wrath in this situation. There are rumors that certain shamans on the isle conceal sacred words or some ancient ritual to waken and command Agyra, and that many of her rampages are not the result of the kaiju being territorial or protective, but simply due to an ancient bargain the natives' ancestors forged with the mighty beast in some forgotten era. Some speculate that such rituals require the sacrifice of trespassers, but this may be nothing more than fearful superstition or rumors spread by shamans to persuade foreigners to stay clear of their island. Agyra has a particular hatred of the kaiju Mogaru, and often leaves her volcanic lair to fly west to the remote jungle lake that serves as Mogaru's home to clash with her nemesis. Mogaru's penchant for attacking coastal cities often results in a devastating escalation when Agyra arrives to do battle with the land-bound kaiju. Sometimes, methods of conjuring Agyra are used to deliberately lure the kaiju to a city besieged by Mogaru, but just as often her arrival seems to be driven by self-interest. Agyra typically manages to weaken Mogaru enough to drive him off, but is often slain herself in these battles, resurrecting and returning to her home at the same time Mogaru returns to his. The nature of this rivalry is unclear, but kaiju scholars believe that the two monsters have been enemies for longer than humanity has existed.","ecology":"","habitat_society":""},{"name":"Baphomet","cr":27,"xp":1638400,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":23,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"see in darkness"},{"type":"true seeing"}],"auras":["frightful presence (180 ft., DC 38)","unholy aura (DC 30)"],"ac":45,"ac_touch":34,"ac_flat_footed":45,"ac_mods":"+4 deflection, +11 Dex, +11 natural, +10 profane, -1 size","hp":643,"hd":"33d10+462","hdvalue":33,"fort":36,"ref":26,"will":31,"defensive_abilities":["Abyssal resurrection","freedom of movement","supernatural cunning"],"dr":"20/cold iron, epic, and good","immunities":["ability damage","ability drain","charm and compulsion effects","death effects","electricity","energy drain","fire","maze","petrification","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30}],"sr":38,"speed":[{"type":"land","speed":50},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"Aizerghaul +52 (2d8+28/19-20/x3), gore +40 (2d8+6 plus 2d6 fire plus burn), bite +40 (1d8+6)","space":"10 ft.","reach":"10 ft. (20 ft. with glaive)","special_attacks":[{"type":"burn","details":"4d6 fire, DC 40"},{"type":"glaive mastery"},{"type":"powerful charge","details":"gore, 4d8+19 plus 2d6 fire and burn"},{"type":"scroll use"}],"spell_like_abilities_caster_level":27,"spell_like_abilities_concentration":41,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"speak with animals"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"baleful polymorph"},{"spell":"blasphemy"},{"spell":"desecrate"},{"spell":"dominate person"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"imprisonment"},{"spell":"mass charm monster"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"maze"},{"spell":"quickened greater dispel magic"},{"spell":"summon demons"},{"spell":"summon minotaurs"},{"spell":"symbol of persuasion"}]}],"strength":36,"dexterity":32,"constitution":38,"intelligence":37,"wisdom":29,"charisma":35,"baseatk":33,"cmb":47,"cmb_special":"+4 vs. bull rush","cmd":82,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Combat Reflexes"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Weapon Focus (glaive)"},{"feat":"Greater Weapon Specialization (glaive)"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (glaive)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (greater dispel magic)"},{"feat":"Scribe Scroll"},{"feat":"Staggering Critical"},{"feat":"Weapon Focus (glaive)"},{"feat":"Weapon Specialization (glaive)"}],"skills":[{"skill":"Acrobatics","value":44},{"skill":"Bluff","value":48},{"skill":"Diplomacy","value":48},{"skill":"Fly","value":49},{"skill":"Handle Animal","value":45},{"skill":"Intimidate","value":45},{"skill":"Knowledge (arcana)","value":49},{"skill":"Knowledge (dungeoneering)","value":46},{"skill":"Knowledge (geography)","value":46},{"skill":"Knowledge (history)","value":46},{"skill":"Knowledge (nobility)","value":46},{"skill":"Knowledge (planes)","value":49},{"skill":"Knowledge (religion)","value":49},{"skill":"Linguistics","value":46},{"skill":"Perception","value":53},{"skill":"Sense Motive","value":45},{"skill":"Spellcraft","value":49},{"skill":"Stealth","value":43},{"skill":"Use Magic Device","value":45}],"languages":["all languages","speak with animals","telepathy 300 ft."],"sq":[{"type":"change shape","details":"any animal, magical beast, or minotaur; greater polymorph"},{"type":"infernal brand"},{"type":"language mastery"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (Aizerghaul, 2d6 scrolls)","description_visual":"Fire burns on the central horn and in the rheumy eyes of this bestial winged demon, who stands more than twice a human's height.","group":"Demon Lord","source":"AP 77","special_abilities":[{"type":"Aizerghaul Aizerghaul","details":"(Abyssal for \"Labyrinth's Final Edge\") is a uniquely shaped glaive, the head of which consists of a double blade akin to a crescent moon. This blade is made of ivory, but is razor sharp and as hard as adamantine (and possesses all the qualities of that material). It is a +5 lawful-outsider-bane unholy wounding glaive capable of inflicting particularly horrible and painful wounds on good-aligned targets and devils alike. Such a creature must succeed at a DC 38 Fortitude save each time it's wounded by Aizerghaul or be sickened with pain for as long as the damage caused by the wound persists. Whether the save succeeds or fails, these wounds don't heal naturally and resist magical healing. A character attempting to heal these wounds must succeed at a DC 32 caster level check or the healing has no effect on the injured creature."},{"type":"Glaive Mastery","kind":"Ex","details":"Baphomet is exceptionally skilled at fighting with a glaive. He is treated as a 20th-level fighter for the purposes of fulfilling any feat prerequisites, such as that for Weapon Specialization."},{"type":"Infernal Brand","kind":"Su","details":"The mark of Asmodeus is branded on Baphomet's brow, yet this is no mark of fealty or servitude. Rather, Baphomet has claimed the pentagram-a remnant of the time he spend as the archdevil's prisoner-and now draws power from it. The brand grants him his devil-like abilities of fire immunity and see in darkness. In addition, all devils and worshipers of devils take a -2 penalty on saving throws against Baphomet's special attacks and spell-like abilities. He gains a +4 bonus on caster level checks to penetrate a devil's spell resistance, and automatically penetrates a devil's damage reduction with his glaive and natural attacks."},{"type":"Language Mastery","kind":"Ex","details":"Baphomet can speak, read, and understand all languages."},{"type":"Scroll Use","kind":"Ex","details":"Baphomet can cast spells from any scroll as if he possessed the spell on a spell list. Spells he casts from scrolls always resolve at caster level 27th."},{"type":"Summon Minotaurs","kind":"Sp","details":"Baphomet can summon half-fiend minotaurs, labyrinth minotaurs, and mythic minotaurs as if casting a summon monster spell. He can summon eight half-fiend minotaurs three times per day, and four mythic minotaurs or one labyrinth minotaur once per day. This ability functions as a swift action, but otherwise works like the summon universal monster rule with 100% chance of success and counts as a 9th-level spell effect."},{"type":"Supernatural Cunning","kind":"Su","details":"Baphomet is never caught flat-footed and gains a +8 bonus on initiative checks. In addition, he's immune to maze spells and can never become lost. He always knows the shortest, most direct route through any maze. After spending 1 minute in any maze, he understands its entire layout implicitly and can teleport to any location using his greater teleport spell-like ability."}],"description":"Baphomet-Lord of the Minotaurs-was created by Lamashtu from the soul of the first minotaur. In those days, he was a powerfully muscled specimen, and the Queen of Demons kept him as a consort until the day Baphomet stole away from her palace in Yanaron, seeking to gain even greater favor by claiming a legendary trophy. Baphomet's ambition was as great as his folly, and he invaded the deepest layer of Hell, intent on stealing Asmodeus's ruby rod for his mistress. Needless to say, he was swiftly caught. Lamashtu claimed no allegiance to him, and Asmodeus imprisoned Baphomet in a devious maze the archdevil proclaimed to be unsolvable, even by the first minotaur. The archdevil also carved his own symbol into Baphomet's brow with the nail of his index finger in an attempt to fully subjugate the minotaur.\n\nBut in this attempt, it was Asmodeus who overstepped his bounds. Not only did Baphomet solve the seemingly unsolvable maze after a mere decade, but as he escaped, he also took the world-sized labyrinth with him. Baphomet had changed over that time, becoming almost emaciated in his build, yet growing much wiser. He did not return to Lamashtu's side, but instead took the archdevil's infernal maze and made it his own as he claimed a portion of the Abyss as his realm.\n\nThis was eons ago, and now Baphomet is a powerful demon lord in his own right. He has forgiven Lamashtu, and serves as her lover now and then, yet he's no longer her direct subservient minion. He works to increase the inf luence of his cult on countless worlds, building his forces so that one day he might again invade Hell. But this time, Baphomet plans on taking much more than Asmodeus's weapon-he intends to take Asmodeus's life!\n\nBaphomet's Cult\n\nBaphomet is worshiped by conspirators, secret societies, corrupted crusaders, and above all else, minotaurs. His minotaur worshipers venerate him openly; in their art, Baphomet is typically depicted as a more classical bull-headed, minotaur-like creature, and when he deigns to appear before these worshipers he often assumes this form. His humanoid worshipers venerate him\n\nin secret, offering prayers and sacrifices in hidden shrines and dark temples beyond the sight of society and communicating in a complex series of hand gestures when in mixed company.\n\nBaphomet has two symbols. To most, including his minotaurs, his symbol is a brass minotaur's head with ruby eyes. His secret societies use this symbol as well, but also mark his works with the inverted pentagram, sometimes decorating the star shape with an image of his face. Baphomet's favored weapon is the glaive, although he doesn't abide any of his followers wielding a weapon that looks like Aizerghaul. He grants access to the domains of Animal, Chaos, Evil, and Strength, and to the subdomains of Demon, Ferocity, Fur, and Resolve.","ecology":"","habitat_society":""},{"name":"Bokrug","cr":27,"xp":3276800,"alignment":"CN","size":"Large","type":"magical beast","subtypes":["aquatic","chaotic","extraplanar","Great Old One"],"init":22,"senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["toxic breath (30 ft., DC 41)","unspeakable presence (300 ft., DC 33)"],"ac":45,"ac_touch":27,"ac_flat_footed":37,"ac_mods":"+8 Dex, +10 insight, +18 natural, -1 size","hp":645,"hd":"30d10+480","hdvalue":30,"hp_mods":["fast healing 20"],"fort":33,"ref":25,"will":22,"defensive_abilities":["immortality","insanity (DC 41)","spines"],"dr":"15/epic and lawful","immunities":["ability damage","ability drain","aging","cold","death effects","disease","energy drain","mind-affecting effects","paralysis","petrification","poison"],"resists":[{"type":"acid","value":30},{"type":"fire","value":30}],"sr":38,"speed":[{"type":"land","speed":50},{"type":"swim","speed":120}],"speed_mod":"air walk","melee":"bite +44 (4d8+22/19-20), 2 claws +44 (2d8+22/19-20), sting +44 (3d6+22/19-20 plus poison), tentacle beard +39 (4d6+22 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"4d6+22"},{"type":"critical poisoning"},{"type":"mythic power","details":"10/day, surge +1d12"},{"type":"poison"},{"type":"powerful blows","details":"bite, claws, sting, tentacle beard"},{"type":"vengeful dreams"}],"spell_like_abilities_caster_level":27,"spell_like_abilities_concentration":43,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"}]},{"frequency":"at-will","spells":[{"spell":"greater dispel magic"},{"spell":"hallucinatory terrain"},{"spell":"mythic cloudkill"},{"spell":"mythic dimension door"},{"spell":"mythic dream"},{"spell":"mythic nightmare"},{"spell":"mythic plane shift"},{"spell":"transmute rock to mud"},{"spell":"wind walk"}]},{"frequency":"1/day","spells":[{"spell":"mythic control weather"},{"spell":"mythic tsunami"},{"spell":"symbol of insanity"}]},{"frequency":"3/day","spells":[{"spell":"demand"},{"spell":"horrid wilting"},{"spell":"quickened feeblemind"}]}],"strength":40,"dexterity":27,"constitution":42,"intelligence":22,"wisdom":30,"charisma":27,"baseatk":30,"cmb":46,"cmb_special":"+4 vs. bull rush, grapple, or overrun","cmd":74,"cmd_special":"+2 vs. bull rush or overrun, +4 vs. trip","feats":[{"feat":"Bleeding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Overrun"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (sting)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Overrun"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (feeblemind)"}],"skills":[{"skill":"Knowledge (arcana, history, nature, religion)","value":36},{"skill":"Perception","value":43},{"skill":"Spellcraft","value":36},{"skill":"Stealth","value":37},{"skill":"Swim","value":56}],"languages":["Aklo","Aquan","Draconic","telepathy 100 ft."],"sq":[{"type":"amphibious"},{"type":"otherworldly insight"}],"environments":["any water"],"organizations":["solitary (unique)"],"treasure":"triple","description_visual":"This great reptilian monster is an aquatic lizard with a beard of tentacles and a sting-tipped tail.","group":"Great Old One","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Critical Poisoning","kind":"Su","details":"If Bokrug confirms a critical hit with his sting, he injects his foe with 3 doses of poison (this increases the save DC by 4). A foe that is normally immune to poison can be affected by Bokrug's poison in this way, but treats the poisoning as if it had been injected with only 1 dose."},{"type":"Immortality","kind":"Ex","details":"If Bokrug is killed, his body immediately begins to thrash and writhe spasmodically, continuing to do so for 1d4 rounds. During this time, he makes a single sting attack against one random target in reach. At the end of this time, his body grows still, then melts into water and evaporates away. Bokrug reforms in dormancy back in his realm in the Dimension of Dreams soon thereafter, remaining in a comatose state for hundreds of years unless he is awoken earlier via complex rituals. Any effect that destroys Bokrug's body (such as disintegrate) merely reduces his remains to water that then evaporates away as described above, but such measures do prevent his body from thrashing and stinging prior to this supernatural evaporation."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 41; frequency 1/round for 6 rounds; effect 2d4 Wisdom damage; cure 3 consecutive saves. A creature whose Wisdom damage equals its Wisdom score automatically becomes afflicted by a random insanity. The save DC is Constitution-based."},{"type":"Spines","kind":"Ex","details":"Any creature that makes a melee attack against Bokrug must succeed at a DC 33 Reflex save or be struck by the numerous swiftly reacting spines that cover the Great Old One, taking 2d6+15 points of damage. Using a reach weapon doesn't endanger the attacker in this way. The save DC is Dexterity-based."},{"type":"Toxic Breath","kind":"Su","details":"Bokrug's breath is toxic. Whenever the Great Old One is above water, he is surrounded by a 30-foot-radius cloud of invisible poison gas that causes temporary madness and hallucinations. Any creature that begins its turn in this area must succeed at a DC 41 Will save or be confused for 1 round. A creature that holds its breath or doesn't have to breathe gains a +4 bonus on this saving throw. This is a mind-affecting poison effect. The save DC is Constitution-based."},{"type":"Unspeakable Presence","kind":"Su","details":"Failing a DC 33 Will save against Bokrug's unspeakable presence causes the victim to become overwhelmed with hopelessness and doom-it takes a -4 penalty on all attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls as long as it remains within the area of affect. The save DC is Charisma-based."},{"type":"Vengeful Dreams","kind":"Su","details":"Any creature that has ever damaged Bokrug or has slain one of his clerics can be targeted by the Great Old One's vengeful dreams regardless of the distance between the creature and Bokrug, even across planar boundaries. In order to use vengeful dreams against a target, Bokrug must successfully affect the target with his nightmare spell-like ability; the target is always treated as familiar to Bokrug, and as if Bokrug possessed a body part of the victim, resulting in a -15 penalty on the saving throw against the nightmare. If the victim fails its save against the nightmare, the horrific dream unfolds as a vision of Bokrug consuming the victim alive. The victim then remains alive, conscious, and aware as the Great Old One digests it, and as Bokrug destroys all that remains of the victim's lifelong friends, home, belongings, and family. When the victim awakens from the nightmare, it must succeed at a DC 33 Will save or take 3d6 points of Wisdom drain from the vengeful dreams. If this drains the target's Wisdom to 0, it automatically gains a random insanity. Once Bokrug uses this ability against a creature, he can't do so again until that creature again damages him or slays one of his clerics. This is a mind-affecting effect. The save DC is Charisma-based."}],"description":"Bokrug, the Water Lizard, dwells in a distant and forsaken corner of the Dimension of Dreams, in a land that was once heavily populated but is now a desolate and barren realm surrounding a nameless lake-a realm once ruled by mighty human empires, but now ruled only by the hideous amphibian minions of the Water Lizard. Bokrug himself is a vast creature, a vaguely iguana-shaped monster with a beard of writhing tendrils and a long tail tipped with a stinger. The scales that cover his body hide long spines that Bokrug can extend or retract with near lightning speed. Bokrug spends the majority of his time slumbering far down in the depths of his submerged lair. No rivers feed the lake, nor does it drain into the sea. Yet the still, ominous waters are neither stale nor brackish, implying that they connect somewhere deep underground, and. By way of these dark, secret waterways, Bokgrug has access to the lakes and rivers of the Dimension of Dreams, and his ability to plane shift allows him access to other realms as he wills.\n\nBOKRUG'S CULT Bokrug is worshiped more out of fear than adoration, and when traveling dreamers come across his cult in their nightmares, they can unknowingly spread this fearful faith into the waking world. Bokrug's temples are often found on the shores of remote lakes or hidden away in large swamplands. Though humans worship him, so do boggards, lizardfolk, marsh giants, and other swamp-dwelling races-particularly those who have suffered at the hands of aggressors, such as invading armies, rival tribes, or adventuring parties. Though Bokrug is chaotic neutral, almost all of his worshipers are chaotic neutral or chaotic evil. Only a rare few chaotic good worshipers of Bokrug exist—most of these being delusional heretics or apologists who seek to keep Bokrug calm, ensuring he continues to slumber. These heretics and outliers of the faith are remorselessly hunted down by his more zealous and traditional worshipers. Bokrug's cult is associated with revenge, storms, and water, and its sacred symbol is a green lizard with a long, coiling tail-an image of Bokrug himself. His greatest shrines feature unusually realistic statues of his form, statues the cult maintains Bokrug can see out of and even animate from his distant lair to take sacrifices. Bokrug's clerics have access to the domains of Chaos, Destruction, Water, and Weather, and to the subdomains of Catastrophe, Oceans, Rage, and Storms. The Water Lizard's favored weapon is the ranseur; his followers often forge their ranseurs' blades to resemble the Great Old One's stingered tail.","ecology":"","habitat_society":""},{"name":"Furcas","cr":27,"xp":3276800,"alignment":"LE","size":"Huge","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect chaos"},{"type":"detect good"},{"type":"see in darkness"},{"type":"true seeing"}],"auras":["frightful presence (120 ft., DC 35)","unholy aura (30 ft., DC 28, 10 rounds)"],"ac":46,"ac_touch":33,"ac_flat_footed":39,"ac_mods":"+4 deflection, +7 Dex, +13 natural, +14 profane, -2 size","hp":635,"hd":"31d10+465","hdvalue":31,"hp_mods":["regeneration (epic and good, good and mythic, or deific)"],"fort":36,"ref":28,"will":27,"defensive_abilities":["armor of thorns","freedom of movement","hellish resurrection","immovable"],"dr":"20/good, epic, and silver","immunities":["ability damage","ability drain","charm effects","compulsion effects","death effects","energy drain","fire","petrification","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30}],"sr":38,"speed":[{"type":"land","speed":50}],"speed_mod":"air walk","melee":"Avernus Claw +48 (2d6+19/19-20 plus 1d6 fire), 2 hooves +44 (1d8+15 plus disease), slam +44 (1d8+15 plus swat)","ranged":"poison barb +36 (1d4+15/19-20 plus poison)","space":"15 ft.","reach":"15 ft. (25 ft. with trident)","special_attacks":[{"type":"crown of laurels"},{"type":"disease"},{"type":"poison"},{"type":"poison barb"},{"type":"powerful hooves"},{"type":"swat"},{"type":"trample","details":"4d8+22, DC 40"}],"spell_like_abilities_caster_level":27,"spell_like_abilities_concentration":42,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect chaos"},{"spell":"detect good"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"blasphemy"},{"spell":"desecrate"},{"spell":"diminish plants"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"plant growth"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"thorny entanglement"},{"spell":"unhallow"},{"spell":"unholy blight"},{"spell":"wall of stone"}]},{"frequency":"1/day","spells":[{"spell":"imprisonment"},{"spell":"meteor swarm"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"overwhelming presence"},{"spell":"quickened fire seeds"},{"spell":"reverse gravity"},{"spell":"summon devils"}]}],"strength":40,"dexterity":24,"constitution":40,"intelligence":29,"wisdom":33,"charisma":31,"baseatk":31,"cmb":48,"cmb_special":"+4 vs. bull rush, +4 vs. disarm","cmd":83,"cmd_special":"immovable +2 vs. bull rush, +2 vs. disarm, +4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Disarm"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (trident)"},{"feat":"Improved Disarm"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (fire seeds)"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Bluff","value":44},{"skill":"Diplomacy","value":44},{"skill":"Handle Animal","value":44},{"skill":"Heal","value":42},{"skill":"Intimidate","value":44},{"skill":"Knowledge (arcana)","value":40},{"skill":"Knowledge (engineering)","value":40},{"skill":"Knowledge (nature)","value":43},{"skill":"Knowledge (planes)","value":43},{"skill":"Perception","value":45},{"skill":"Profession (herbalist)","value":42},{"skill":"Sense Motive","value":45},{"skill":"Spellcraft","value":40},{"skill":"Stealth","value":33},{"skill":"Use Magic Device","value":41}],"languages":["Abyssal","Celestial","Common","Draconic","Dwarven","Elven","Infernal","Sylvan","telepathy 300 ft."],"sq":[{"type":"infernal duke traits"},{"type":"irresistible force"}],"environments":["any (Hell)"],"organizations":["solitary (unique)"],"treasure":"triple standard (Avernus Claw)","description_visual":"This giant, centaurlike creature's body is made of hardened, thorny vines. A crown of laurels graces its brow.","group":"Infernal Duke","source":"Hell Unleashed","special_abilities":[{"type":"Armor of Thorns","kind":"Ex","details":"A network of thorny vines armors and invades Furcas's body. Any creature that strikes Furcas with a non-reach melee weapon, unarmed strike, or natural weapon takes 1d8+7 points of piercing damage from the barbs studding the infernal duke's body and must succeed at a DC 40 Fortitude saving throw or be poisoned (potentially in addition to the effects of unholy aura). This living, toxic armor also feeds off of all manner of corruption. Any attempt to poison Furcas or magically control his vine armor heals him for 4d6 points of damage. Furcas can also use his poison barbs to heal himself in this way."},{"type":"Crown of Laurels","kind":"Su","details":"Once per day as a move action, Furcas can bestow his laurel crown upon an adjacent creature. For the next 24 hours, the creature is affected as per the spells greater heroism and unholy aura. At the end of this period, these benefits cease and the creature is infected with a particularly resilient form of devil chills. This version requires six consecutive successful saving throws to cure, and can be magically cured only by a lawful evil spellcaster. Creatures immune to disease suffer no negative effects. The crown always returns to Furcas after 24 hours."},{"type":"Disease","kind":"Su","details":"Devil chills: hooves-injury; save Fort DC 40; onset immediate; frequency 1/day; effect 1d3 Str damage; cure 3 consecutive saves. The save DC is Constitution-based."},{"type":"Immovable","kind":"Ex","details":"While conscious, Furcas cannot be moved, tripped, or knocked prone by any attack, combat maneuver, spell, or similar effect generated by any creature lesser than a deity or object of less than artifact-level power."},{"type":"Irresistible Force","kind":"Su","details":"Anytime Furcas's attack moves a foe-whether through the use of a combat maneuver, Awesome Blow, telekinesis, or a similar effect-that creature is moved double the normal distance."},{"type":"Poison","kind":"Ex","details":"Poison barb-injury; save Fort DC 20; frequency 1/round for 10 rounds; effect fatigued; cure 3 consecutive saves. The save DC is Constitution-based."},{"type":"Poison Barb","kind":"Su","details":"As a standard action, Furcas can grow and fire a toxic barb from his body. This is a ranged attack with a range increment of 60 ft. Any creature struck by the barb must succeed at a DC 40 Fortitude saving throw or be poisoned. Furcas can decide what type of poison the barb bears, whether his own fatiguing toxin or any poison conveyed through injury. After using this ability, Furcas cannot grow another barb for 1d4 rounds."},{"type":"Powerful Hooves","kind":"Ex","details":"Furcas's hoof attacks are considered primary attacks. He always adds his full Strength bonus to the amount of damage dealt by his hooves."},{"type":"Swat","kind":"Ex","details":"As a free action, Furcas can use the Awesome Blow feat with his slam attack. Because of his irresistible force ability, any creature affected by this attack is hurled 20 ft."}],"description":"Called the Knight of the Laurels and the Sentinel of Dis, Furcas is the infernal duke of duty, flames, and herbalism. His disparate concerns model him as a true knight of Hell, a sentry armed with fire and girded by thorns. His patience and wisdom make him one of the multiverse's greatest military commanders, but also a sage of all things green and growing. It might take eons, but Furcas knows that a relentless will can forge even the most delicate petal into a weapon deadlier than any spear.\n\nWhile laurels do crown Furcas's brown, his title stems from the tangle of parasitic, cassytha-like growths that riddle the remains of his stern, once-angelic form. These vines constitute a mighty, tauric body-one that serves as armor for the infernal duke and as a bed for innumerable toxic plants. Furcas is rarely seen without the Avernus Claw, a trident gifted to him by Typhon, the deceased former archdevil of Avernus. The burning trident holds\n\nthe power to block any escape from the first layer of Hell, and serves as Furcas's divine symbol.\n\nAs Furcas's demesne-the Hanging Marches-lies on Avernus, the infernal duke is the subject of the layer's ruler, Barbatos. However, Furcas also maintains strong ties with Dis, the second layer of Hell, and its imperious ruler, the archdevil Dispater. These dual loyalties stem from the ancient hellmouth Voulgaz, which yawns at the center of Furcas's realm. The infernal duke's fortress, the Forked Pyre, guards the hellmouth and serves as the stronghold from which Furcas oversees his legions as they conduct travelers and damned souls into the plane-city beyond. Furcas has overseen this post for countless eons, and despite numerous sieges by celestials and proteans alike, the gate to Dis has never fallen.\n\nWhether seeking to reclaim a damned soul (rightfully or otherwise), to gain some wisdom of the natural world, or to secure passage to Dis, characters with business in Hell are likely to travel through the Hanging Marches. This is made all the easier from Golarion by a permanent portal that connects a forested valley within Brevoy's Icerime Peaks with Olikscourt, a toppled outpost on the shore of the Crawling Sea. Few who trespass in the Hanging Marches escape the notice of the Knight of the Laurels.","ecology":"","habitat_society":""},{"name":"Xoveron","cr":27,"xp":3276800,"alignment":"CE","size":"Huge","type":"outsider","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["frightful presence (120 ft., DC 35)","unholy aura (DC 27)"],"ac":45,"ac_touch":30,"ac_flat_footed":39,"ac_mods":"+4 deflection, +6 Dex, +15 natural, +12 profane, -2 size","hp":643,"hd":"33d10+462","hdvalue":33,"hp_mods":["regeneration 30 (mythic or deific)"],"fort":36,"ref":23,"will":33,"defensive_abilities":["Abyssal resurrection","freedom of movement"],"dr":"20/cold iron, good, and epic","immunities":["ability damage and drain","acid","charm and compulsion effects","death effects","electricity","level drain","petrification","poison"],"resists":[{"type":"cold","value":30},{"type":"fire","value":30}],"sr":38,"speed":[{"type":"land","speed":50},{"type":"fly","speed":80,"maneuverability":"good"}],"melee":"4 claws +48 (1d8+17/19-20), 4 bites +48 (2d6+17/19-20), sting +48 (1d8+17/19-20 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"devastating blow"},{"type":"feed"},{"type":"poison"},{"type":"rend","details":"2 claws, 2d8+25"},{"type":"roar"},{"type":"shatter petrification"},{"type":"shockwave"}],"spell_like_abilities_caster_level":27,"spell_like_abilities_concentration":41,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"desecrate"},{"spell":"flesh to stone"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"stone shape"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"implosion"},{"spell":"imprisonment"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"earthquake"},{"spell":"quickened flesh to stone"},{"spell":"reverse gravity"},{"spell":"symbol of weakness"}]}],"strength":44,"dexterity":23,"constitution":38,"intelligence":24,"wisdom":32,"charisma":28,"baseatk":33,"cmb":52,"cmb_special":"+4 vs. bull rush, +4 vs. sunder","cmd":86,"cmd_special":"+2 vs. bull rush, +2 vs. sunder","feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Sunder"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (sting)"},{"feat":"Improved Lightning Reflexes"},{"feat":"Improved Sunder"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (flesh to stone)"}],"skills":[{"skill":"Acrobatics","value":39,"special":"+47 when jumping"},{"skill":"Disable Device","value":42},{"skill":"Fly","value":42},{"skill":"Intimidate","value":45},{"skill":"Knowledge (arcana)","value":40},{"skill":"Knowledge (religion)","value":40},{"skill":"Knowledge (engineering)","value":43},{"skill":"Knowledge (planes)","value":43},{"skill":"Perception","value":55},{"skill":"Sense Motive","value":47},{"skill":"Spellcraft","value":43},{"skill":"Stealth","value":34},{"skill":"Use Magic Device","value":42}],"languages":["Abyssal","Celestial","Common","Draconic","Terran","telepathy 300 ft."],"environments":["any (Abyss)","any (Ghahazi)"],"organizations":["solitary (unique)"],"treasure":"triple","description_visual":"This hulking, four-armed, four-headed, sting-tailed gargoyle stands as tall as a house.","group":"Demon Lord","source":"AP 73","special_abilities":[{"type":"Devastating Blow","kind":"Su","details":"As a standard action, Xoveron can bring all four of his claws to bear upon a single target. It this attack hits, he deals 8d8+68 points of bludgeoning damage. If the target is a creature, it must make a successful DC 43 Fortitude save or be knocked prone and staggered for 1d4 rounds. If the target is an object, the attack ignores all hardness possessed by the object. The save DC is Strength-based."},{"type":"Feed","kind":"Su","details":"Xoveron can consume the corpse of a Large or smaller creature that has been dead no longer than a day as a full-round action. Doing so destroys the creature's body and leaves its gear scattered on the ground. All armor and gear worn in the body slot must make a successful DC 43 Fortitude save to avoid becoming broken by this swift and violent consumption. When Xoveron feeds on a creature, he immediately learns all of that creature's memories and knowledge. In addition, he gains the effects of a heal spell and a haste spell (both at CL 27th). The save DC is Strength-based."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 40; frequency 1/round for 6 rounds; effect 1d6 Dexterity drain; cure 3 consecutive saves. If a creature's Dexterity is drained to 0, the creature is immediately petrified. The save DC is Constitution-based."},{"type":"Roar","kind":"Su","details":"Xoveron can unleash a devastating roar as a standard action once per hour. When he roars, all creatures and unattended objects within 60 ft. take 30d10 points of sonic damage and become stunned for 1d6 rounds. Xoveron doesn't take this damage, and he can exclude any number of creatures or objects from this effect as he wills. A successful DC 40 Reflex save halves the damage and negates the stun effect. The save DC is Constitution-based."},{"type":"Shatter Petrification","kind":"Su","details":"Xoveron can strike a petrified creature with any one of his natural weapon attacks to cause it to shatter. The petrified creature can resist this with a successful DC 43 Fortitude save. If the creature fails to resist, the blow smashes it apart into an explosion of razor sharp stone fragments. Any creature within 10 ft. of a shattering petrified creature takes 10d6 points of piercing and slashing damage from these flying fragments of once-living flesh (Reflex DC 43 half). Xoveron is never damaged by these flying shards of stone. The save DC is Strength-based."},{"type":"Shockwave","kind":"Su","details":"When Xoveron makes a charge attack while flying and lands at the end of the charge, the force of his landing creates a powerful shockwave. All creatures standing on the ground within 30 ft. of Xoveron when he lands at the end of a charge attack must make a successful DC 40 Reflex save to avoid being knocked prone by the force of the impact. The save DC is Constitution-based."}],"description":"Xoveron, the Horned Prince, is the demon lord of gargoyles, gluttony, and ruins. It is said that he can look out through the eyes of all stone gargoyles perched on roofs throughout the world, watching and waiting for cities to fall, that he might visit and feed on those left behind. Xoveron himself towers at a height of 25 ft., with a wingspan of just over 50 ft. When the Horned Prince moves, the sound of stone grinding on stone can be heard, as if the demon lord himself were composed not of flesh but of some unholy stone come to demonic life.\n\nXoveron is often accompanied by numerous vrolikai and ulkreth demons. Gargoyles of tremendous size often serve at the Horned Prince's whim, as do monsters with a reputation for hunger and gluttony, such as purple worms or man-eating animals. His realm on the Abyss is an immense, ruined city called Ghahazi, said to have been constructed over the eons by the Horned Prince, who plucked decaying districts and crumbling structures from dead cities across countless worlds.\n\nXoveron's Cult\n\nXoveron is traditionally worshiped by gargoyles, although as the Age of Lost Omens has drawn on, his worship among humanoids has been increasing steadily, particularly among bandits, brigands, gluttons, and those who dwell in blasted, apocalyptic regions such as the Worldwound and the Sodden Lands. In such regions, the landscapes of ruined cities and devastated skylines appeal to those who worship the Horned Prince; his cultists raise temples to their demonic patron there in caverns, on ruined rooftops, or within the skeletal frames of partially collapsed cathedrals to gods whose faith and worship alike have moved on. Defenestration is far and away the favored method of sacrifice for his cult.\n\nIn addition to gargoyles, the cult is particularly fond of and even subservient to the nabasu demons. Often, a cult of Xoveron seeks out a newly \"born\" nabasu and offers itself to the demon. Usually this means the demon takes a few of the cultists to feed on and demands the survivors seek out more victims on a regular basis, but in some cases the ravenous newborn nabasu simply consumes the entire cult. To the fanatic of Xoveron, though, such a fate is worth dying for.\n\nXoveron's unholy symbol is a five-horned gray gargoyle skull that's missing its lower jaw. His favored weapon is the ranseur. He grants access to the domains of Chaos, Earth, Evil, and Strength, and to the subdomains of Caves, Demon, Entropy, and Ferocity. Entropy is a subdomain of Chaos.","ecology":"","habitat_society":""},{"name":"Dagon","cr":28,"xp":3276800,"alignment":"CE","size":"Huge","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar","water"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["frightful presence (120 ft., DC 36)","unholy aura (DC 28)"],"ac":46,"ac_touch":31,"ac_flat_footed":39,"ac_mods":"+4 deflection, +7 Dex, +15 natural, +12 profane, -2 size","hp":676,"hd":"33d10+495","hdvalue":33,"hp_mods":["regeneration 30 (deific or mythic)"],"fort":37,"ref":24,"will":7,"defensive_abilities":["Abyssal resurrection","freedom of movement"],"dr":"20/cold iron, epic, and good","immunities":["ability damage","ability drain","charm effects","compulsion effects","cold","death effects","electricity","energy drain","petrification","and poison"],"resists":[{"type":"acid","value":30},{"type":"fire","value":30}],"sr":39,"speed":[{"type":"land","speed":40},{"type":"swim","speed":120}],"melee":"bite +48 (6d6+17/19-20 plus grab), 4 tentacles +43 (2d6+8/19-20 plus grab)","space":"15 ft.","reach":"15 ft. (30 ft. with tentacle)","special_attacks":[{"type":"breath weapon"},{"type":"command aquatic creature"},{"type":"constrict","details":"2d6+25"},{"type":"fast swallow"},{"type":"poison"},{"type":"swallow whole","details":"transformation, AC 17, 67 hp"}],"spell_like_abilities_caster_level":28,"spell_like_abilities_concentration":43,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"speak with animals","details":"aquatic animals only"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"control water"},{"spell":"control weather"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"storm of vengeance"},{"spell":"time stop"},{"spell":"tsunami"}]},{"frequency":"3/day","spells":[{"spell":"insanity"},{"spell":"quickened greater dispel magic"},{"spell":"summon demons"},{"spell":"symbol of insanity"},{"spell":"vortex"}]}],"strength":44,"dexterity":25,"constitution":40,"intelligence":29,"wisdom":32,"charisma":31,"baseatk":33,"cmb":14,"cmd":27,"cmd_special":"+4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (greater dispel magic)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":40,"special":"+44 when jumping"},{"skill":"Bluff","value":46},{"skill":"Intimidate","value":46},{"skill":"Knowledge (arcana)","value":45},{"skill":"Knowledge (geography)","value":42},{"skill":"Knowledge (history)","value":42},{"skill":"Knowledge (nature)","value":45},{"skill":"Knowledge (planes)","value":45},{"skill":"Knowledge (religion)","value":42},{"skill":"Perception","value":55},{"skill":"Sense Motive","value":47},{"skill":"Spellcraft","value":45},{"skill":"Stealth","value":35},{"skill":"Swim","value":61},{"skill":"Use Magic Device","value":43}],"languages":["Abyssal","Aquan","Celestial","Common","Draconic","speak with animals (aquatic animals only)","telepathy 300 ft."],"sq":[{"type":"compression"},{"type":"demon lord traits"}],"environments":["any oceans (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple","description_visual":"This demon's body is a nightmare of writhing tentacles and slippery coils below the leering maw of a deep sea predator.","group":"Demon Lord","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds as a standard action, Dagon can exhale a 60-foot cone of inky blackness. Underwater, this cone manifests as black ink, while above water it manifests as a thick cloud. Creatures in the area have their vision obscured as if they were in complete darkness. Darkvision doesn't allow someone to see through the ink or smoke, but true seeing does. The ink or smoke persists for 1d4 rounds, but dissipates in 1 round in areas with aquatic currents or winds. Any creature in the breath weapon's area is exposed to the breath weapon's poison and must succeed at a DC 41 Will save or gain 2 negative levels as its memories and knowledge leach away (this is a mind-affecting effect). Any creature that enters the ink or cloud, or ends its turn inside it, must succeed at another Will save (at a +4 bonus) to avoid further level loss and poisoning. The save DC is Constitution-based."},{"type":"Command Aquatic Creature","kind":"Su","details":"Dagon can command aquatic creatures to do his bidding as a move action, either via using his ability to speak with animals or via telepathy. This affects all aberrations, animals, magical beasts, oozes, and vermin within 300 ft. that have the aquatic subtype (Will DC 36 negates). This functions like mass suggestion, but can affect mindless creatures. Dagon can suggest obviously harmful or suicidal acts (though non-mindless creatures gain a +10 bonus on their saving throws against these suggestions). The commanded course of activity can have a duration of up to 1 hour. If Dagon issues a new command to a creature, the previous command is discarded. Once a creature succeeds at its save against this effect, it is immune to further commands from Dagon for 24 hours. The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Breath weapon-contact; save Fort DC 41; frequency 1/round for 6 rounds; effect 1d6 Con drain and confused for 1 round; cure 3 consecutive saves."},{"type":"Transformation","kind":"Su","details":"A creature swallowed by Dagon is assaulted by demonic enzymes, rasping talons, sucking tendrils, and vile gases. At the start of the swallowed creature's turn, it must succeed at a DC 41 Fortitude save or be nauseated, and must succeed at a DC 36 Will save or take 1d6 points of Dexterity and Charisma drain. Once the creature's Dexterity and Charisma are drained to 0, the creature transforms into a horrifically deformed version of itself that Dagon can then disgorge into any adjacent square as a swift action. The transformed creature gains the half-fiend template, its Dexterity and Charisma return to their normal values, and it is under Dagon's control (as dominate monster, caster level 28th). The transformation can be reversed by casting break enchantment and atonement on the victim during the first 24 hours (after that, it can be reversed only via miracle or wish). The Fortitude save DC is Constitution-based, and the Will save DC is Charisma-based."}],"description":"Dagon is the demon lord of deformity, the sea, and sea monsters. He rules an Abyssal realm that consists of an immense ocean dotted above with strange and horrible islands and marked below with countless deep sea trenches and sunken cities. Dagon is 35 ft. long, with the lower body of an eel, a horrific visage that evokes images of deep sea predators, and four long tentacles in place of arms. Dagon almost always uses Power Attack in combat, taking a -9 penalty on all attack rolls but gaining a +18 bonus on damage rolls. He is never encountered without a large number of aquatic demons or monsters at his side that he uses as pawns in battles, often simply commanding them to attack foes while he hangs back in the shadows and observes the fight with his cold eyes. Immense sharks, hezrous, carnivorous whales, krakens, and shoggoths are the demon lord's favored minions. Dagon began life not as a demon lord but as a powerful qlippoth-the reasons for his transformation into a demon lord are not understood by mortal scholars, but there is certainly no love lost between Dagon and the qlippoth race.\n\nDAGON'S CULT\n\nDagon is worshiped primarily by boggards, heretical sahuagin and skum, marsh giants, and desperate or insane coastal dwellers. Most of his worshipers are grotesquely deformed or engage in various abhorrent practices of interbreeding with strange ichthyic or aquatic creatures that dwell nearby. His holy places are often decaying seaside churches, lighthouses, sea caves, or darkly beautiful underwater cathedrals. Often his worshipers also venerate various Great Old Ones, in particular Cthulhu, and it's not unusual to find priests of Dagon and Cthulhu working side by side in a community. Dagon is also known as the Shadow in the Sea. His unholy symbol is a gold disk inscribed with sinister runes around an open octopus eye. His favored weapon is the trident. He grants access to the domains of Chaos, Destruction, Evil, and Water, and access to the subdomains of Catastrophe, Demon, Oceans, and Rage.","ecology":"","habitat_society":""},{"name":"Shax Demon Lord","cr":28,"xp":4915200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":18,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["bleeding wounds (30 ft.)","frightful presence (120 ft., DC 36)","unholy aura (DC 28)"],"ac":46,"ac_touch":38,"ac_flat_footed":32,"ac_mods":"+14 Dex, +8 natural, +14 profane","hp":676,"hd":"33d10+495","hdvalue":33,"hp_mods":["regeneration 30 (deific or mythic)"],"fort":26,"ref":32,"will":7,"defensive_abilities":["absorb blood","Abyssal resurrection","freedom of movement"],"dr":"20/cold iron, epic, and good","immunities":["ability damage and drain","bleed","charm and compulsion effects","death effects","electricity","energy drain","poison","petrification"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":39,"speed":[{"type":"land","speed":50}],"melee":"+5 unholy dagger +46 (1d4+15/17-20), +5 unholy dagger +46 (1d4+15/17-20), bite +38 (1d6+5)","ranged":"thrown surgical tool +47 (1d6+10)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"command blood"},{"type":"frightful weapon prowess"},{"type":"painful cuts"},{"type":"sneak attack","details":"+5d6"}],"spell_like_abilities_caster_level":28,"spell_like_abilities_concentration":43,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"blood biography"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"spiritual weapon"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"finger of death"},{"spell":"time stop"},{"spell":"weird"}]},{"frequency":"3/day","spells":[{"spell":"blade barrier"},{"spell":"mage's sword"},{"spell":"summon demons"},{"spell":"symbol of pain"}]}],"strength":30,"dexterity":39,"constitution":40,"intelligence":30,"wisdom":31,"charisma":31,"baseatk":33,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":32,"cmd_special":"+12 vs. trip","feats":[{"feat":"Blinding Critical"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Critical Focus"},{"feat":"Double Slice"},{"feat":"Greater Disarm"},{"feat":"Greater Two-Weapon Fighting"},{"feat":"Improved Critical (dagger)"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Improvised Weapon Mastery"},{"feat":"Quick Draw"},{"feat":"Throw Anything"},{"feat":"Two-Weapon Fighting"},{"feat":"Two-Weapon Rend"}],"skills":[{"skill":"Acrobatics","value":50},{"skill":"Bluff","value":46},{"skill":"Craft (alchemy)","value":46},{"skill":"Disable Device","value":50},{"skill":"Fly","value":47},{"skill":"Heal","value":43},{"skill":"Intimidate","value":46},{"skill":"Knowledge (arcana)","value":43},{"skill":"Knowledge (engineering)","value":21},{"skill":"Knowledge (planes)","value":46},{"skill":"Knowledge (religion)","value":43},{"skill":"Perception","value":54},{"skill":"Sense Motive","value":46},{"skill":"Sleight of Hand","value":47},{"skill":"Spellcraft","value":43},{"skill":"Stealth","value":50},{"skill":"Use Magic Device","value":46}],"languages":["Abyssal","Celestial","Common","Draconic","telepathy 300 ft."],"sq":[{"type":"master of lies"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (2 +5 unholy daggers)","description_visual":"This stork-headed, winged humanoid is spattered with blood and wields a pair of gory, razor-sharp daggers in his dripping hands.","group":"Demon Lord","source":"AP 74","special_abilities":[{"type":"Absorb Blood","kind":"Su","details":"If a creature dies while under the effects of Shax's ability to command blood, all of the victim's blood slithers out of its body and moves at a speed of 60 ft. toward Shax. If the slithering blood reaches Shax, it flows up onto his body and is absorbed, affecting Shax as a heal spell (CL 28th). A slithering pool of blood can be destroyed by any amount of fire damage applied to it before it reaches its goal, or by the application of an effect that transmutes liquid to something other than blood."},{"type":"Aura of Bleeding Wounds","kind":"Su","details":"Whenever a creature takes piercing or slashing damage within 30 ft. of Shax, it takes an additional 1d6 points of bleed damage. This bleed damage stacks with itself, up to a maximum of 10d6 points. As a free action, Shax may designate any number of creatures within the aura to be exempt from this effect."},{"type":"Command Blood","kind":"Su","details":"As a swift action, Shax can command the blood of any creature that is currently suffering from bleed damage to do his bidding. The target must be within 60 ft. of Shax for him to use this ability. The target can resist this ability with a successful DC 36 Fortitude save. If the target fails the save, Shax can command the victim's blood to behave in one of the manners listed below. Once commanded, the blood continues to function in this way for as long as the victim continues to bleed. Shax can change the effect in a subsequent round by using this ability again, but no more than one of the following effects can be in effect at any one time. The save DC is Charisma-based. Blinding Blood: The victim's blood runs up into its eyes and blinds it at the start of its turn unless the victim takes a move action to wipe away the blood. Once a victim is blinded in this way, it remains blinded as long as the bleed effect continues. Bloody Mess: The victim's blood spreads out across its body, making it slippery. This grants a +10 circumstance bonus on Escape Artist checks and all attempts to resist being grappled, but the victim must succeed at a DC 36 Reflex save at the start of each round or drop objects it holds. These effects last as long as the bleed effect continues. Choking Blood: The target's blood runs up into its nostrils and mouth unless the creature uses a free hand to pinch its nose shut and holds its breath. If the target doesn't do so, the blood runs into its lungs and the creature must succeed at a Constitution check each round or it begins to drown. Once a victim begins to drown, it continues to do so as long as the bleed effect persists. Gruesome Tendrils: This effect automatically ends any bleed effects the victim is currently suffering as it causes the blood coating the victim to solidify into thin, whiplike tendrils that lash out at any creature within 5 ft. Any creature that begins its turn in this area automatically takes 1d6 points of slashing damage and 1d6 points of bleed damage; a successful DC 36 Reflex save prevents this damage."},{"type":"Frightful Weapon Prowess","kind":"Ex","details":"When an opponent observes Shax's attacks, the frightening display of the demon lord's grace makes the victim take additional damage from those attacks, as if simply imagining the damage were enough to cause injury. Shax gains a profane bonus equal to his Charisma modifier on damage rolls (+10 damage) with all weapon attacks and ranged attacks made against a victim who can observe him. This damage is negated if the victim closes its eyes, but doing so puts the opponent in greater danger from Shax's sneak attacks. This is a visual fear effect."},{"type":"Master of Lies","kind":"Ex","details":"Shax is immune to any magical effect that discerns lies or forces him to speak the truth."},{"type":"Painful Cuts","kind":"Ex","details":"Whenever Shax threatens a critical hit with a slashing weapon, the victim must succeed at a DC 36 Fortitude save or be staggered by the pain for 1 round. If the hit was a critical hit, the staggered effect lasts for 1d4 rounds on a failed saving throw. The save DC is Charisma-based."}],"description":"Shax is the demon lord of envy, lies, and-above all else-murder. He rules an Abyssal realm known as Charnelhome, an immense mansion the size of a city perched atop a slanted bluff surrounded by a bog of thorny, blood-drinking plants. He is fond of inviting his captured enemies as well as his greatest worshipers into the chambers of this building, for those who survive his deathtraps often serve as lessons as to how he can improve his methods of mayhem.\n\nShax is particularly skilled at blinding foes with critical hits-when he does so, he likes to pluck the eyes from his victim's face as part of the attack and swiftly gobble them down whole. He can hurl the countless surgical tools he carries on his body as deadly weapons, but prefers to slaughter foes in melee.\n\nShax'sCult\n\nBabaus, chokers, derros, drow, evil nobles, serial killers, and torturers worship Shax by inf licting grisly torments on other conscious and living souls. The subjects of these tortures aren't always unwilling or innocent victims, although his cultists prefer tormenting enemies of the faith over allies or members. The cult's holy places are narrow alleyways in violent parts of large cities, hidden rooms in grand estates, and secret dungeons filled with deathtraps and torture chambers. These unholy temples are often guarded by fiendish animals (particularly large, predatory birds) and shadow demons, but are usually watched over by a number of babau demons as well. Enhanced versions of these demons, called the Sons of Shax, and can be found serving his greatest cults.\n\nShax's unholy symbol is a curved white feather sitting in a pool of blood. His favored weapon is the dagger. He grants access to the domains of Chaos, Destruction, Evil, and Nobility, and to the subdomains of Demon, Leadership, Martyr, and Rage. For more rules about demon lords, including the full rules of Shax's Abyssal resurrection and summon demons abilities.","ecology":"","habitat_society":""},{"name":"Mogaru","cr":28,"xp":4915200,"alignment":"CN","size":"Colossal","type":"magical beast","subtypes":["kaiju","water"],"init":9,"senses":[{"type":"darkvision","modifier":"600 ft."},{"type":"low-light vision"},{"type":"see invisibility"},{"type":"sense kaiju"}],"ac":47,"ac_touch":7,"ac_flat_footed":42,"ac_mods":"+5 Dex, +40 natural, -8 size","hp":697,"hd":"34d10+510","hdvalue":34,"hp_mods":["fast healing 30"],"fort":34,"ref":24,"will":23,"defensive_abilities":["absorb energy","ferocity","recovery"],"dr":"20/ epic","immunities":["ability damage","ability drain","death effects","disease","energy drain","fire","and fear"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"electricity","value":30},{"type":"negative energy","value":30},{"type":"sonic","value":30}],"weaknesses":["susceptible to song"],"speed":[{"type":"land","speed":100},{"type":"swim","speed":100}],"melee":"bite +46 (8d6+20/19-20 plus grab), 2 claws +46 (4d8+20/19-20), 2 tail slaps +44 (6d6+10/19-20)","ranged":"firebolts +31 touch (damage variable; see below)","space":"60 ft.","reach":"60 ft.","special_attacks":[{"type":"breath weapon"},{"type":"ferocity"},{"type":"fast swallow"},{"type":"hurl foe"},{"type":"reflexive breath"},{"type":"swallow whole","details":"10d6 bludgeoning and 10d6 fire damage, AC 30, 69 hp"},{"type":"trample","details":"4d8+30, DC 47"}],"strength":50,"dexterity":21,"constitution":41,"intelligence":3,"wisdom":30,"charisma":26,"baseatk":34,"cmb":62,"cmb_special":"+4 vs. bull rush, +4 vs. grapple, +4 vs. sunder","cmd":79,"cmd_special":"+2 vs. bull rush, +2 vs. sunder","feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Bull Rush"},{"feat":"Greater Sunder"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Perception","value":45},{"skill":"Swim","value":49}],"languages":["Aquan (can't speak)"],"sq":[{"type":"massive"}],"environments":["warm forests","warm water"],"organizations":["solitary (unique)"],"treasure":"incidental","description_visual":"This towering saurian lumbers on its hind legs, its twin tails thrashing and the spines on its back glowing with red energy.","group":"Kaiju","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Absorb Energy","kind":"Ex","details":"Mogaru absorbs energy attacks that damage him, including negative energy attacks. Damage blocked by one of his resistances or immunities instead heals him an amount equal to the damage dealt. He may absorb only one kind of energy in this manner in a round. The first type of energy that affects him in a round (whether or not it penetrates his immunities or resistance to actually damage him) sets the type of energy he absorbs for that round. Hit points gained in excess of his normal maximum are lost. Mogaru cannot gain healing from energy effects generated by himself."},{"type":"Breath Weapon","kind":"Su","details":"Once every 4 rounds, Mogaru can breathe out a beam of fiery red force. When Mogaru uses this attack, he can choose to focus the breath weapon into a single 1,200-foot-long line, or he can shorten the range and turn his head and body while breathing, effectively affecting a 600-foot-long cone. All creatures caught in this area of effect take 20d6 points of fire damage, 20d6 points of force damage, and are staggered for 1d6 rounds from the devastating energy (Reflex DC 42 halves the damage and prevents the staggered effect). A creature slain by this effect is disintegrated, whether the saving throw was successful or not. This breath weapon is particularly effective at blasting through cover-cover doesn't grant any bonuses on Reflex saves against Mogaru's breath weapon. The save DC is Constitution-based."},{"type":"Firebolts","kind":"Su","details":"As a standard action on any round immediately following the use of his breath weapon, Mogaru can fire bolts of red energy from the glowing spines along his back. These bolts are ranged touch attacks with a range of 1,200 ft. When Mogaru uses this ability, he must choose between firing one firebolt, three firebolts, or six firebolts. If he fires one, it deals 20d6 points of damage on a hit. If he fires three bolts, each deals 8d6 points of damage on a hit. If he fires six bolts, each deals 5d6 points of damage on a hit. Half of the damage caused by any one firebolt is fire damage, the other half is force damage. Firebolts deal full damage against objects, and ignore the first 10 points of hardness possessed by an object."},{"type":"Reflexive Breath","kind":"Ex","details":"The first time in any round that Mogaru can make an attack of opportunity, he can choose to use a diminished version of his breath weapon instead of making a physical attack. This reflexive breath weapon attack only targets the creature that provoked the attack of opportunity, but otherwise causes the same damage and effects his breath weapon normally inflicts (Reflex DC 32 halves the damage and negates the staggered effect). Use of his breath weapon in this way doesn't affect the recharge rate of the regular breath weapon. The save DC is Constitution-based, and includes a -10 penalty to reflect the fact that the reflexive breath is a shorter (but no less intense) blast of energy than the kaiju's typical breath weapon attack."},{"type":"Sense Kaiju","kind":"Su","details":"Mogaru can sense the location of the nearest active kaiju, as if using discern location, at will."},{"type":"Susceptible to Song","kind":"Ex","details":"Mogaru's actions can be influenced by song, provided the kaiju notices the singing. If the kaiju isn't currently engaged in battle, he automatically hears any song within 100 ft. that is directed at him in an attempt to influence him, but when he is in combat, there's only a cumulative 20% chance per round of sustained singing that he notices the song. In order to influence Mogaru, the singer must make a DC 35 Perform (sing) check (this check cannot be bolstered by the aid another action, and the singer cannot take 10 or 20 on the check). The result of this check sets the DC of the Will save Mogaru must make in order to not be influenced by the song. The singer can choose to influence Mogaru as if she had successfully cast suggestion on the kaiju (CL = the singer's ranks in Perform [sing]). If Mogaru succeeds at a Will save (DC = the singer's ranks in Perform [sing] + the singer's Charisma modifier), the effects of the influence last for a maximum of 1d4 rounds; otherwise, the effects last as long as a suggestion spell would normally last. Mogaru cannot use his recovery ability to recover from song influence, and a single singer may influence Mogaru only once per day."}],"description":"Mogaru, known as the Final King to kaiju scholars, or simply as King Mogaru, is one of the most destructive of his kind. Although not the most powerful kaiju (a sobering thought in and of itself), Mogaru is certainly the most active of the known kaiju. Additionally, Mogaru seems to be as eager to rampage through the works of humanity as he is to attack and kill other kaiju, making him something of a mixed blessing to kaiju-threatened cities. While the prospect of an attack by Mogaru is the stuff of nightmares, the possibility of his intervention during a different kaiju attack is the stuff of hope, though the damage dealt to a city during its defense may be significant. Mogaru appears as a towering dinosaur with twin tails, spines that glow red as he uses his breath weapon, and two powerful clawed forearms. King Mogaru dwells in the depths of a tropical jungle, sleeping silently at the bottom of an unusually deep lake until roused. Legends hold that Mogaru was born of the world itself, either formed from the spirits of countless plants and animals resulting from ages of hunting and predation by humanoids for food or sport, or formed from the souls of the countless slain in an ancient apocalypse or war that devastated one of the first of the world's empires. Regardless of the actual cause, the birth of Mogaru in these legends seems to be the same-soon after another kaiju, Lord Varklops, emerged from an erupting volcano, Mogaru rose to oppose the Thrice-Headed Fiend in a vast battle that nearly slew Varklops while devastating an entire nation in the process. Mogaru is also rumored to have slain no fewer than a dozen other kaiju, including Agmazar the Star Titan, now believed to be the only undead kaiju in existence. Of particular note is the curious fact that Mogaru exhibits a particularly unique interest in song. Legends of skilled singers being able to save their cities with a single mournful paean to the kaiju, or of vengeful bards using their craft to waken the monster from his lair to send him on a rampage are common along coastal regions with a history of kaiju attacks, and in such regions renowned singers are well respected for this ability to inf luence one of the world's most destructive creatures. Kaiju scholars suspect that song manages to penetrate Mogaru's memories of some primeval event, but the reasons for the kaiju's reaction to the song are its own. Mogaru stands 140 ft. high and weighs 20,000 tons, and is nearly 300 ft. long from nose to tail.","ecology":"","habitat_society":""},{"name":"Sifkesh","cr":28,"xp":4915200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":12,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["frightful presence (120 ft., DC 38)","unholy aura (20 ft., DC 31)"],"ac":49,"ac_touch":43,"ac_flat_footed":36,"ac_mods":"+4 deflection, +12 Dex, +1 dodge, +6 natural, +16 profane","hp":666,"hd":"31d10+496","hdvalue":31,"hp_mods":["regeneration 30 (deific or mythic)"],"fort":30,"ref":33,"will":30,"defensive_abilities":["critical healing","freedom of movement","heretical"],"dr":"20/cold iron, epic, and good","immunities":["ability damage and drain","bleed","charm and compulsion effects","death effects","electricity","energy drain","petrification","poison","slashing weapons"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":39,"speed":[{"type":"land","speed":30},{"type":"fly","speed":120,"maneuverability":"perfect"}],"melee":"+5 unholy speed war razor +47 (1d4+27/19-20), claw +42 (4d6+27/19-20 plus 1d4 Cha drain)","space":"5 ft.","reach":"30 ft.","special_attacks":[{"type":"Charisma drain"},{"type":"despairing cry"},{"type":"precise cuts"},{"type":"suicide"}],"spell_like_abilities_caster_level":28,"spell_like_abilities_concentration":44,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"crushing despair"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"suggestion"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"sympathy"},{"spell":"time stop"},{"spell":"weird"}]},{"frequency":"3/day","spells":[{"spell":"demand"},{"spell":"quickened dominate person"},{"spell":"quickened suggestion"},{"spell":"summon demons"},{"spell":"symbol of strife"}]}],"strength":32,"dexterity":35,"constitution":42,"intelligence":33,"wisdom":29,"charisma":36,"baseatk":31,"cmb":42,"cmd":85,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (war razor)"},{"feat":"Improved Critical (claw)"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (dominate person, suggestion)"},{"feat":"Spring Attack"},{"feat":"Staggering Critical"},{"feat":"Whirlwind Attack"}],"skills":[{"skill":"Acrobatics","value":46},{"skill":"Bluff","value":47},{"skill":"Diplomacy","value":47},{"skill":"Fly","value":54},{"skill":"Intimidate","value":44},{"skill":"Knowledge (arcana)","value":42},{"skill":"Knowledge (engineering)","value":42},{"skill":"Knowledge (history)","value":42},{"skill":"Knowledge (local)","value":42},{"skill":"Knowledge (nobility)","value":45},{"skill":"Knowledge (planes)","value":45},{"skill":"Knowledge (religion)","value":42},{"skill":"Perception","value":51},{"skill":"Sense Motive","value":43},{"skill":"Spellcraft","value":45},{"skill":"Stealth","value":46},{"skill":"Use Magic Device","value":44}],"languages":["Abyssal (can't speak)","Celestial (can't speak)","Common (can't speak)","telepathy 300 ft."],"sq":[{"type":"demon lord traits"},{"type":"detached limbs"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (+5 unholy speed war razor)","description_visual":"This gaunt woman has blood-soaked hair, eyes and lips stitched shut with wire, and severed limbs that float nearby as if they were still attached.","group":"Demon Lord","source":"AP 75","special_abilities":[{"type":"Charisma Drain","kind":"Su","details":"Sifkesh's claw leaves hideous scars that resist healing even via magic; these scars manifest as Charisma drain. The more scars a victim gains in this manner, the more despondent and depressed its personality grows. A creature whose Charisma score is drained to 3 or lower by this attack automatically fails any Will save against any spell-like ability or supernatural attack made by Sifkesh. A successful DC 41 Will save resists the Charisma drain inflicted by this attack, and instead causes the victim to be sickened for 1 round. The save DC is Charisma-based."},{"type":"Critical Healing","kind":"Ex","details":"Critical hits cause Sifkesh to experience a sudden rush of energy and healing. Any additional damage dealt to Sifkesh by a critical hit actually heals her of that amount of damage rather than harming her. This damage applies simultaneously to the attack's normal damage, and can prevent her from being slain if the damage from the normal attack would otherwise have been enough to kill her. Sifkesh takes no damage at all (but neither does she gain healing) from critical hits she or her allies deal to her-only attempts to actually damage her can heal her in this way. Whenever Sifkesh is healed of any damage in this manner, she becomes hasted for 1 round. Sifkesh takes normal damage from sneak attacks and other precision-based damage."},{"type":"Despairing Cry","kind":"Su","details":"Once every 1d4 rounds as a swift action, Sifkesh can unleash a soul-rending mournful scream that affects all creatures in a 60-foot-radius spread. A creature in this area must attempt a successful DC 38 Will save or be overcome by suicidal despair-on a successful save, a creature is merely sickened for 1d4 rounds. A creature fully affected by this special attack takes a -6 penalty on attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls, and cannot gain the benefit of any morale bonus for 24 hours. A creature that is normally immune to fear loses that ability while under the effects of despairing cry, and can be ordered to take obviously suicidal acts while under the influence of effects like charm person, dominate person, and suggestion. The effects of multiple despairing cries don't stack. This is a mind-affecting sonic curse effect. The save DC is Charisma-based."},{"type":"Detached Limbs","kind":"Su","details":"Sifkesh's arms, legs, and head are not physically attached to her torso. Instead, they float in approximately the positions they would normally take up, but never quite perfectly aligned. She is immune to any effect that severs limbs or her head. In addition, when she attacks, her limbs can move with surprising speed, effectively granting her exceptional reach for a Medium creature."},{"type":"Heretical","kind":"Ex","details":"Sifkesh's heretical persona protects her from servants of faith. Against any spell cast by a divine spellcaster, her Spell Resistance increases to 41, and she gains a +2 bonus on all saving throws against such spells. A divine spellcaster who willingly touches Sifkesh must succeed at a DC 38 Will save or be nauseated for 1d4 rounds. The save DC is Charisma-based."},{"type":"Immune to Edged Weapons","kind":"Ex","details":"Sifkesh is immune to all forms of slashing damage and bleed effects."},{"type":"Precise Cuts","kind":"Ex","details":"Sifkesh deals an amount of additional damage equal to her Intelligence bonus on any successful attack that deals slashing damage."},{"type":"Suicide","kind":"Su","details":"Once per day as an immediate action, Sifkesh can drop her defenses when attacked by a foe. She is treated as flat-footed for this attack, loses her profane bonus to her AC and spell resistance, and automatically fails any saving throws against that attack. If this attack kills her, she immediately utters her despairing cry (even if she's already used it within the previous 1d4 rounds). Any creatures affected by this particular despairing cry are also stunned for 1d4 rounds. One round after she commits suicide, Sifkesh automatically comes back to life, as if affected by true resurrection."}],"description":"Sifkesh, the Sacred Whore, is the demon lord of suicide, heresy, and hopeless despair. She rules the Abyssal realm of Vantian, the legendary City of Open Windows. The city itself is constantly destroying itself, as its buildings continually plummet into the churning surf along an eternally crumbling coastline.\n\nSifkesh is among the most enigmatic of all demon lords, for she seems more diabolic or even daemonic in her personality and appearance. Planar scholars have long struggled to interpret the demon lord's position and power. The belief that Sifkesh rose from the animus of a heretical erinyes who became the first of Hell's heretics is correct, and she constantly works to seduce and lure additional powerful devils from their infernal roles, inviting some to join her as favored minions but leaving others in place so they can more easily work to subvert Hell's machinations.\n\nSifkesh's Cult\n\nSifkesh is worshiped by blasphemers, heretics, outcasts from other religions, and survivors of botched suicide attempts. Her faithful are relatively solitary individuals, and there isn't a strong element of group worship of the demon lord-her cults tend to be small and often amount to only a single worshiper who might employ or rule his own group of minions or followers who don't actually serve the Sacred Whore. Worship of Sifkesh is a deeply personal and secretive thing, and many of her followers publicly belong to other religions, worshiping the demon lord of heresy in secret as they work to undermine the faith their allies and companions believe them to have. Holy sites to Sifkesh include desecrated churches, haunted houses, and towers with too many windows-nearly always, such temples and shrines to Sifkesh are empty and abandoned. The lone worshiper might share the site with other creatures such as predators or undead, and may even rely upon the presence of such creatures as convenient protection and defense against the enemy.\n\nSifkesh's unholy symbol is a pair of feminine hands crossed at slashed wrists. Her favored weapon is the war razor. She grants access to the domains of Chaos, Evil, Madness, and Trickery, and to the subdomains of Deception, Demon, Loss, and Nightmare (even though she normally wouldn't be able to grant access to the subdomain of Loss, she can do so due to her close associations with despair and hopelessness).","ecology":"","habitat_society":""},{"name":"Vildeis","cr":28,"xp":4915200,"alignment":"LG","size":"Large","type":"outsider","subtypes":["angel","extraplanar","good","lawful"],"init":13,"senses":[{"type":"blindsense","modifier":"120 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"true seeing"},{"type":"zealous vision"}],"auras":["primal (30 ft.)","protective"],"ac":44,"ac_touch":19,"ac_flat_footed":34,"ac_mods":"+9 Dex, +1 dodge, +25 natural, -1 size | +4 deflection vs. evil","hp":610,"hd":"33d10+429","hdvalue":33,"hp_mods":["regeneration 10 (evil artifacts, effects, and spells)"],"fort":31,"ref":20,"will":26,"save_mods":"+4 vs. poison, +4 vs. evil","dr":"15/epic and evil","immunities":["ability damage","ability drain","acid","bleed","charm effects","compulsion effects","cold","death effects","energy drain","petrification"],"resists":[{"type":"electricity","value":30},{"type":"fire","value":30}],"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"Cicatrix +50 (1d6+17/17-20 plus 1 bleed and 2d6 vicious)","ranged":"Cicatrix +47 (1d6+17/17-20 plus 1 bleed)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"smite evil","details":"7/day, +5 attack and AC, +20 damage, disintegrate evil outsiders"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":37,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"command"},{"spell":"greater teleport"},{"spell":"haste"},{"spell":"pain strike"},{"spell":"paladin's sacrifice"}]},{"frequency":"3/day","spells":[{"spell":"discern location"},{"spell":"geas/quest"},{"spell":"heal"},{"spell":"holy word"},{"spell":"mark of justice"},{"spell":"mass pain strike"},{"spell":"searing light"}]}],"spellsprepared_caster":"paladin","spellsprepared_caster_level":20,"spellsprepared_concentration":37,"spellsprepared":[{"spell_level":4,"spell_slots":1,"spells":[{"spell":"blaze of glory"},{"spell":"break enchantment"},{"spell":"death ward"},{"spell":"king's castle"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"dispel magic"},{"spell":"fires of judgment"},{"spell":"prayer"},{"spell":"righteous vigor"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"bull's strength"},{"spell":"corruption resistance"},{"spell":"litany of warding"},{"spell":"remove paralysis"},{"spell":"shield other"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"divine favor","count":3},{"spell":"hero's defiance"},{"spell":"lesser restoration","count":2}]}],"strength":35,"dexterity":29,"constitution":37,"intelligence":18,"wisdom":22,"charisma":21,"baseatk":33,"cmb":46,"cmd":66,"feats":[{"feat":"Blinding Critical"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (dagger)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Spell Penetration"},{"feat":"Step Up"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (dagger)"}],"skills":[{"skill":"Acrobatics","value":45},{"skill":"Bluff","value":41},{"skill":"Fly","value":26},{"skill":"Heal","value":23},{"skill":"Intimidate","value":41},{"skill":"Knowledge (planes)","value":40},{"skill":"Knowledge (religion)","value":40},{"skill":"Perception","value":42},{"skill":"Sense Motive","value":42},{"skill":"Sleight of Hand","value":45},{"skill":"Stealth","value":41}],"languages":["Celestial","Draconic","truespeech"],"sq":[{"type":"lay on hands","details":"16d6, 25/day"},{"type":"seed of life"}],"environments":["any (Heaven)"],"organizations":["unique"],"treasure":"standard (Cicatrix)","description_visual":"This red-winged angel is blindfolded and wrapped with bloody bandages. What shows of her flesh is scarred with celestial runes.","group":"Empyreal Lord","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Primal Aura","kind":"Su","details":"Whenever Vildeis would be affected by a bleed effect, all enemies within 30 ft. gain that bleeding condition instead, as though they were the effect's original targets (no saving throw, creatures immune to bleeding are immune to this effect). The Heal DC to stop this bleeding is 25."},{"type":"Smite Evil","kind":"Su","details":"Vildeis can smite evil as a 20th-level paladin. Whenever she uses smite evil and successfully strikes an evil outsider, the outsider is also subject to disintegrate, using Vildeis's paladin level as the caster level. After the disintegrate effect and the damage from the attack are resolved, the smite effect immediately ends. Spells Vildeis casts spells as a 20th-level paladin."},{"type":"Zealous Vision","kind":"Su","details":"Vildeis automatically pinpoints the location of any evil creature within 1,000 ft. of her."}],"description":"Also known as the Cardinal Martyr, Vildeis endlessly sacrifices herself in penitence for the sins of the multiverse, every battle against evil giving her body one more wound with which she might shed bloody tears for existence. When Vildeis emerged from the Heavens, she was a being of sublime beauty, but of a majesty so delicate that she couldn't suffer the sight or even the thought of evil. Within an hour of her birth, she had put out her own eyes, refusing to even gaze upon a reality tainted by sin. Since the first self-inflicted wound marred her once-perfect body, she has struggled against evil in all its forms. Denying herself home or rest, Vildeis harrows the wildest reaches of the multiverse, driving back the expansions of foul realms and slaying those who would do wicked deeds. Vildeis has no home among the planes, and forgoes any comforts-even those as basic as shelter or company-so long as there is evil afoot in the multiverse. Such makes her one of the most aloof empyreal lords, but also one of the most storied. Across the planes, legends tell of pitched battles, desperate last stands, and near massacres turned in the favor of the innocent by the sudden appearance of Vildeis herself, bloody-winged and avenging. While such miraculous rescues have more to do with happenstance then omniscience, they nonetheless inf lame the passions of the righteous across countless worlds. Those who seek to encounter the empyreal lord of devotion, sacrifice, and scars must follow rumors of her passing, usually spoken by awed beings and crippled fiends along the fringes of reality's darkest outlands. Nearly as well known as the Cardinal Martyr herself are her morbid trappings-miles of stained bandages, scars etched and re-etched in the shapes of celestial runes, and a dagger that drips with her blood as often as that of her enemies. Of these, her dagger Cicatrix is the most infamous, a black blade like a thorn dropped from some gigantic iron rose, which the empyreal lord used to blind herself. Tales tell that she uses her blade not just to slay the wicked and share her blindness, but to carve the runes that crisscross her body upon others, infusing them with the compulsion to battle evil even if previously there was no such desire.\n\nVILDEIS'S FAITH Vildeis is the patron of devotion, sacrif ice, and scars. Those who follow her number among the most zealous crusaders, the most unshakable priests, and the most incorruptible judges. They view their goddess as an exemplar and a leader who sacrifices for them in ways they can never match. Vildeis, and by extension her worshipers, is extremely strict when it comes to adhering to her tenets of living an austere and principled life wholly devoted to combating evil. Those who diverge from Vildeis's teachings are expelled from her orders, but encouraged to do good in the world under the service of gentler masters. Though Vildeis doesn't expect all of her followers to perform the same self-mortification that she does, tattoos, scarification, and flagellation are common among her servants, especially her most devoted priests. Even those who don't engage in ritual bloodletting typically wear long red ribbons, symbolic of the empyreal lord's eternal wounds. Vildeis's holy symbol is a scarred golden breastplate. Her favored weapon is the dagger. Her clerics have access to the Destruction, Good, Healing, and Law domains, and to the Rage and Resurrection subdomains.","ecology":"","habitat_society":""},{"name":"Deskari","cr":29,"xp":6553600,"alignment":"CE","size":"Gargantuan","type":"outsider","subtypes":["chaotic","demon","earth","evil","extraplanar"],"init":14,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"swarmsight"},{"type":"true seeing"}],"auras":["frightful presence (180 ft., DC 36)","unholy aura (DC 28)"],"ac":47,"ac_touch":32,"ac_flat_footed":37,"ac_mods":"+4 deflection, +10 Dex, +15 natural, +12 profane, -4 size","hp":742,"hd":"33d10+561","hdvalue":33,"hp_mods":["regeneration 30 (epic and good or deific)"],"fort":31,"ref":32,"will":12,"defensive_abilities":["Abyssal resurrection","all-around vision","freedom of movement","rasping armor"],"dr":"20/cold iron, epic, and good","immunities":["ability damage and drain","charm and compulsion effects","death effects","electricity","energy drain","petrification","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":40,"speed":[{"type":"land","speed":60},{"type":"climb","speed":60},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"Riftcarver +51 (4d6+30/19-20/x4 plus poison), bite +41 (2d8+8 plus poison), sting +41 (2d6+8 plus poison)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"breath weapon"},{"type":"enhanced venom"},{"type":"infestation"},{"type":"poison"},{"type":"swarm master"}],"spell_like_abilities_caster_level":29,"spell_like_abilities_concentration":45,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"control winds"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"hungry pit"},{"spell":"insect plague"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"earthquake"},{"spell":"imprisonment"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"control weather"},{"spell":"creeping doom"},{"spell":"reverse gravity"},{"spell":"summon demons"},{"spell":"symbol of weakness"}]}],"strength":44,"dexterity":30,"constitution":42,"intelligence":29,"wisdom":31,"charisma":31,"baseatk":33,"cmb":14,"cmd":26,"feats":[{"feat":"Awesome Blow"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Flyby Attack"},{"feat":"Greater Sunder"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (scythe)"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":46,"special":"+58 when jumping"},{"skill":"Bluff","value":46},{"skill":"Climb","value":74},{"skill":"Disable Device","value":46},{"skill":"Fly","value":44},{"skill":"Intimidate","value":43},{"skill":"Knowledge (arcana)","value":42},{"skill":"Knowledge (dungeoneering)","value":42},{"skill":"Knowledge (engineering)","value":42},{"skill":"Knowledge (planes)","value":42},{"skill":"Perception","value":54},{"skill":"Sense Motive","value":46},{"skill":"Spellcraft","value":45},{"skill":"Stealth","value":34},{"skill":"Use Magic Device","value":46}],"languages":["Abyssal","Celestial","Common","Draconic","Terran","Undercommon","telepathy 300 ft."],"sq":[{"type":"wall crawler"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (Riftcarver)","description_visual":"Larger than an elephant, this towering insectile nightmare wields a scythe made of bone. Its wings are swarms of biting flies, and its inhuman eyes glitter with cruel intelligence.","group":"Demon Lord","source":"AP 78","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds as a swift action, Deskari can spit out a line of noxious black slime in a 120- foot line that creates a 20-foot-radius-spread puddle of the stuff on the ground where the line terminates. Any creature caught in this area of effect takes 20d10 points of acid damage and is subject to the effects of Deskari's poison. A successful DC 42 Reflex save halves the damage, but doesn't mitigate the poison's effects. The line and puddle created by this attack remain as active acid on the ground for 1d4 rounds, affecting any creatures that move through an affected area. Damage caused by this breath weapon doesn't persist into additional rounds, but on the round a creature takes this damage, it is considered to be taking continuous damage for the purposes of spellcasting and concentration checks. The save DC is Constitution-based."},{"type":"Enhanced Venom","kind":"Su","details":"Any poisons created by Deskari (or even those used by him) become enhanced, and can affect creatures normally immune to poison. If an affected creature is mythic and is normally immune to poison, it instead receives a +4 bonus on its saving throw against Deskari's poison effects."},{"type":"Infestation","kind":"Su","details":"Whenever a creature becomes poisoned by Deskari, it also becomes infested with thousands of microscopic demonic eggs that quickly multiply and spread throughout the victim's bloodstream and flesh alike. Once infested, a creature remains infested even after the poison's effects end or are cured. A creature that has been infested by Deskari is recognized by all mindless swarms as a host, and such swarms never deal damage to the creature unless influenced and compelled to do so by an outside influence. An infested creature takes a -4 penalty on all saving throws made against Deskari's attacks or spells cast by his clerics. As a swift action, Deskari may command a creature's infestation to accelerate; this deals 20d6 points of damage and stuns the target for 1 round (a successful DC 42 Fortitude save halves the damage and negates the stun effect) as the eggs hatch and a fiendish locust swarm bursts out of the creature's body (ending the infestation). Infestation is a disease effect, and the save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Bite, breath weapon, sting, or Riftcarver-injury; save Fort DC 42; frequency 1/round for 6 rounds; effect 1d4 Constitution drain plus infestation; cure 3 consecutive saves. The save DC is Constitution-based."},{"type":"Rasping Armor","kind":"Su","details":"The armor plates that protect Deskari's body rasp together whenever he is damaged by a physical attack, creating a discordant shrieking and grinding sound. Every time a creature strikes Deskari with an attack that deals bludgeoning, force, piercing, or slashing damage, all creatures within 10 ft. of Deskari must succeed at a DC 42 Fortitude save or be sickened for 1d6 rounds. A sickened creature that fails this save becomes staggered for 1 round. A staggered creature that fails this save becomes nauseated for 1 round. Finally, a nauseated creature that fails this save becomes stunned for 1d6 rounds. This is a mind-affecting sonic effect that doesn't affect demons. The save DC is Constitution-based."},{"type":"Swarm Master","kind":"Su","details":"Deskari is immune to swarm damage and other swarm effects (such as distraction). As a swift action, he can direct the movement of any swarm within 30 ft. An intelligent swarm can resist this compulsion by succeeding at a DC 36 Will save. Any swarm created by or conjured by Deskari deals +3d6 points of swarm damage, and the damage caused by such a swarm is treated as chaotic, epic, and evil for the purpose of overcoming damage reduction. The save DC is Charisma-based."},{"type":"Swarmsight","kind":"Su","details":"Deskari can see through the eyes of any swarm he commands or controls, including the swarm of biting flies that makes up his wings (this swarm, incidentally, grants him all-around vision)."},{"type":"Wall Crawler","kind":"Su","details":"Deskari can climb any vertical surface with ease and never has to attempt Climb checks to avoid falling as a result of taking damage. This grants him a +16 racial bonus on Climb checks."}],"description":"Known as the Lord of the Locust Host and the Usher of the Apocalypse, Deskari has long plagued the region of Sarkoris, ever since he discovered a strange thinness between that nation and his own Abyssal realm. His first attempt to capitalize upon this strange feature ended with his defeat at Aroden's hands, but after the god's death at the outset of the Age of Lost Omens, Deskari and his cult wasted no time in opening the Worldwound to allow the demon lord's plans for Golarion to continue.\n\nDeskari carved his realm from the raw matter of the Abyss using a great scythe called Riftcarver, a weapon he crafted from the remains of the strange creature his father, Pazuzu, mated with tens of thousands of years ago. Today, Pazuzu and Deskari have what passes as a cordial relationship-the two demon lords don't work together, but neither do they oppose each other's goals on the Material Plane and beyond.\n\nDeskari's Cult\n\nDeskari is worshiped primarily by the denizens of the Worldwound on Golarion-by tief lings, fallen crusaders, demons, half-fiends, and all manner of other vile creatures that dwell within that devastated land.\n\nDeskari's symbol is a pair of crossed locust wings dripping with blood. His favored weapon is the scythe, in honor of his devastating weapon of choice, Riftcarver, but his worshipers sometimes prefer to use smaller weapons, especially when they must move unnoticed among enemies. Deskari grants access to the domains of Chaos, Destruction, Evil, and War, and to the subdomains of Blood, Catastrophe, Demons, and Tactics.","ecology":"","habitat_society":""},{"name":"Hastur","cr":29,"xp":6553600,"alignment":"CE","size":"Medium","type":"aberration","subtypes":["chaotic","evil","Great Old One"],"init":26,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"auras":["unspeakable presence (300 ft., DC 40)"],"ac":48,"ac_touch":37,"ac_flat_footed":31,"ac_mods":"+16 Dex, +1 dodge, +10 insight, +11 natural","hp":731,"hd":"34d8+578","hdvalue":34,"hp_mods":["fast healing 25"],"fort":28,"ref":27,"will":29,"defensive_abilities":["freedom of movement","immortality","insanity (DC 40)"],"dr":"15/epic and lawful","immunities":["ability damage","ability drain","aging","cold","death effects","disease","energy drain","mind-affecting effects","paralysis","petrification","sonic"],"resists":[{"type":"acid","value":30},{"type":"electricity","value":30},{"type":"fire","value":30}],"sr":40,"speed":[{"type":"land","speed":80}],"speed_mod":"air walk","melee":"4 tattered lash +41 (2d8+7 plus bleed)","space":"5 ft.","reach":"40 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"fulvous dreams"},{"type":"mythic power","details":"10/ day, surge +1d12"},{"type":"reveal visage"},{"type":"sneak attack","details":"+10d6"},{"type":"Yellow Sign"}],"spell_like_abilities_caster_level":29,"spell_like_abilities_concentration":46,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"freedom of movement"},{"spell":"tongues"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"greater dispel magic"},{"spell":"insanity"},{"spell":"mirage arcana"},{"spell":"mythic dimension door"},{"spell":"mythic dream"},{"spell":"mythic enervation"},{"spell":"mythic nightmare"},{"spell":"mythic sending"},{"spell":"mythic wish","details":"see below"},{"spell":"veil"}]},{"frequency":"1/day","spells":[{"spell":"symbol of death"},{"spell":"symbol of fear"},{"spell":"symbol of insanity"},{"spell":"symbol of pain"},{"spell":"symbol of persuasion"},{"spell":"symbol of strife"},{"spell":"symbol of stunning"},{"spell":"symbol of weakness"}]},{"frequency":"3/day","spells":[{"spell":"demand"},{"spell":"interplanetary teleport"},{"spell":"mass suggestion"},{"spell":"project image"},{"spell":"quickened feeblemind"}]}],"strength":24,"dexterity":43,"constitution":44,"intelligence":35,"wisdom":31,"charisma":36,"baseatk":25,"cmb":41,"cmd":69,"cmd_special":"can't be tripped","feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Greater Feint"},{"feat":"Greater Vital Strike"},{"feat":"Improved Critical (tattered lash)"},{"feat":"Improved Feint"},{"feat":"Improved Vital Strike"},{"feat":"Mobility"},{"feat":"Quicken Spell-Like Ability (feeblemind)"},{"feat":"Spring Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"},{"feat":"Whirlwind Attack"}],"skills":[{"skill":"Acrobatics","value":53,"special":"+73 when jumping"},{"skill":"Bluff","value":47},{"skill":"Disguise","value":47},{"skill":"Intimidate","value":50},{"skill":"Knowledge (arcana, geography, history, local)","value":46},{"skill":"Knowledge (nobility)","value":49},{"skill":"Perception","value":47},{"skill":"Perform (act)","value":47},{"skill":"Sense Motive","value":44},{"skill":"Sleight of Hand","value":50},{"skill":"Spellcraft","value":49},{"skill":"Stealth","value":53},{"skill":"Use Magic Device","value":47}],"languages":["Aklo","telepathy 100 ft.","tongues"],"sq":[{"type":"otherworldly insight"}],"environments":["any"],"organizations":["solitary (unique)"],"treasure":"triple","description_visual":"This entity appears to be a skeletal human form hidden under tattered yellow robes, but it moves with unsettling, inhuman grace.","group":"Great Old One","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Fulvous Dreams","kind":"Su","details":"When Hastur uses his nightmare spell-like ability on a creature that has seen the Yellow Sign, he also afflicts that creature with horrifying dreams tinted with a nauseating yellow color and thick with overwhelming sensations of decadence, shame, and entropic disorder. In addition to the effect of nightmare, the target must also succeed at a DC 40 Will save or be compelled to seek out a Yellow Sign, throwing all of his resources and actions into the obsession. While obsessed, the target takes a -4 penalty on Will saving throws, saving throws against symbol spells, concentration checks, and Wisdom-based skill checks. This obsession effect ends immediately if the victim looks upon the Yellow Sign. This is a mind-affecting curse effect. The save DC is Charisma-based."},{"type":"Immortality","kind":"Ex","details":"If Hastur is slain, the robes that drape his frame suddenly drop to the ground as if whatever shape supported them had suddenly ceased to exist. The robes themselves remain inanimate on the ground, but any humanoid creature that touches them must succeed at a DC 40 Will save to resist a sudden urge to put the robes on. Doing so is a full-round action that provokes attacks of opportunity. Once it has donned Hastur's robes, the creature immediately perishes and its body is destroyed. In its place, Hastur lives again, as if brought back via true resurrection. If the discarded robes are not donned within 24 hours, they fade away, leaving behind a faint yellow stain. In this case, Hastur can't manifest a physical body again until the conditions are right, or until an unwitting cultist or fool calls him forth once again. The save DC is Charisma-based."},{"type":"Reveal Visage","kind":"Su","details":"As a swift action, Hastur may reveal to one adjacent creature the true shape beneath his robes. The creature must succeed at DC 40 Will save or be paralyzed for 1d4 rounds and take 1d4 points of Wisdom drain at the end of its turn each round the paralysis lasts, though the revelation is too awful for memory to retain. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Tattered Lash","kind":"Ex","details":"Hastur attacks with long strips of his tattered yellow robes. These strips have a reach of 40 ft. and are primary natural slashing attacks. Bleed damage from the strips stacks with itself (up to 10d6 points of bleed damage). Hastur treats insane targets as if they were flat-footed when he attacks with these weapons."},{"type":"Unspeakable Presence","kind":"Su","details":"Failing a DC 40 Will save against Hastur's unspeakable presence afflicts a creature with a random insanity. A creature that is already insane instead becomes confused for as long as it remains in the area. The save DC is Charisma-based."},{"type":"Wish","kind":"Sp","details":"Although Hastur may use wish as a spell-like ability at will, he can do so only to grant the wishes of other creatures, and only once per creature. Invariably, the results of these wishes serve somehow to advance Hastur's agenda."},{"type":"Yellow Sign","kind":"Su","details":"Once per day as a free action, Hastur can touch any solid surface and inscribe the Yellow Sign upon it. Once inscribed, the Yellow Sign remains for a year, but is active only on certain nights when the light from Hastur's distant world shines in the night sky as a star. Any creature that looks upon an active Yellow Sign must succeed at a DC 40 Will save to avoid becoming dominated by Hastur (as dominate monster); whether or not the save is successful, the creature doesn't have to save against that Yellow Sign again for 24 hours. While the creature is under this domination effect, if the creature's Charisma drain plus Charisma damage ever equal its Charisma score, it immediately dies and allows Hastur to manifest physically at the location of its corpse, as if the victim had donned Hastur's tattered robes (see immortality). A Yellow Sign can be removed with dispel chaos, dispel evil, or erase, any of which requires the caster to succeed at a DC 35 caster level check. Mage's disjunction automatically removes a Yellow Sign. This is a mind-affecting effect. The save DC is Charisma-based."}],"description":"Hastur is the most mysterious of the Great Old Ones. In fact, the entity known as Hastur might actually be an Outer God. The physical manifestation of this entity is known as the King in Yellow, and though most consider this creature-a vaguely human-shaped figure draped in a yellow cloak-to be synonymous with Hastur himself, many scholars believe that the King in Yellow isn'thing more than an avatar used by the true Hastur to move among the denizens of the physical world. Hastur himself is said to dwell upon a distant world called Carcosa on the shores of the monstrous Lake of Hali, and his power on a planet is strongest when the baleful light of Carcosa's star is visible in that planet's night sky.\n\nHASTUR'S CULT Hastur's cult is primarily composed of decadent nobles, playwrights, and aristocrats who have grown bored with life and have sought out increasingly deviant, bizarre, and self-destructive methods of achieving gratification in life. His temples are opulent and excessive-opera houses, manors, and the like that contain hidden chambers for pastimes best indulged in secret. His cultists are particularly eager to bring innocents into their fold, exposing them to the Yellow Sign so that their bodies and minds can serve as portals through which the King in Yellow may walk the world. Hastur's cult is associated with decadence, disorder, and nihilism, and its symbol is the Yellow Sign. The least varieties of these symbols are nonmagical-and somewhat inaccurate-representations of the sigil, though the more powerful cults possess methods by which they can craft fully functional Yellow Signs. Unlike those created by Hastur, a cult-created Yellow Sign can be resisted with a successful DC 23 Will save (as if it were a 9th-level spell). Hastur's clerics have access to the domains of Chaos, Evil, Rune, and Void, and to the subdomains of Dark Tapestry, Language, Stars, and Wards. Hastur's favored weapon is the rapier.","ecology":"","habitat_society":""},{"name":"Cernunnos","cr":30,"xp":9830400,"alignment":"CG","size":"Large","type":"outsider","subtypes":["azata","chaotic","extraplanar","good"],"init":16,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"detect lies"},{"type":"detect poison"},{"type":"low-light vision"},{"type":"true seeing"}],"auras":["primal (30 ft.)"],"ac":48,"ac_touch":22,"ac_flat_footed":35,"ac_mods":"+12 Dex, +1 dodge, +26 natural, -1 size","hp":663,"hd":"34d10+476","hdvalue":34,"hp_mods":["regeneration 10 (evil artifacts, effects, and spells)"],"fort":25,"ref":31,"will":25,"defensive_abilities":["freedom of movement","lightning rod","unbound"],"dr":"15/epic and evil","immunities":["ability damage","ability drain","charm effects","compulsion effects","death effects","electricity","energy drain","petrification"],"resists":[{"type":"cold","value":30},{"type":"fire","value":30}],"sr":41,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"+5 holy cold iron club +48 (1d8+18/15-20), gore +43 (2d8+18)","ranged":"+5 evil outsider bane composite longbow +51 (2d6+14/19-20/x4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"greater slaying arrow"},{"type":"horned lord's charge"},{"type":"powerful charge","details":"gore, 4d8+13 and horned lord's charge"},{"type":"wild shape","details":"as 20th level druid"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":34,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect lies"},{"spell":"detect poison"},{"spell":"freedom of movement"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport"},{"spell":"haste"},{"spell":"true strike"}]},{"frequency":"1/day","spells":[{"spell":"discern location"},{"spell":"mage's disjunction"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"break enchantment"},{"spell":"breath of life"},{"spell":"dimensional anchor"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":20,"spellsprepared_concentration":34,"spellsprepared":[{"spell_level":9,"spell_slots":1,"spells":[{"spell":"elemental swarm"},{"spell":"foresight"},{"spell":"summon nature's ally IX","count":2}]},{"spell_level":8,"spell_slots":1,"spells":[{"spell":"control plants"},{"spell":"repel metal or stone"},{"spell":"sunburst"},{"spell":"whirlwind"}]},{"spell_level":7,"spell_slots":1,"spells":[{"spell":"control weather"},{"spell":"creeping doom"},{"spell":"heal"},{"spell":"sunbeam"}]},{"spell_level":6,"spell_slots":1,"spells":[{"spell":"antilife shell"},{"spell":"greater dispel magic","count":2},{"spell":"move earth"},{"spell":"wall of stone"}]},{"spell_level":5,"spell_slots":1,"spells":[{"spell":"atonement"},{"spell":"baleful polymorph"},{"spell":"deathward"},{"spell":"transmute rock to mud"},{"spell":"wall of thorns"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"cure serious wounds","count":2},{"spell":"freedom of movement"},{"spell":"rusting grasp"},{"spell":"true form"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"call lightning"},{"spell":"cure moderate wounds"},{"spell":"neutralize poison","count":2},{"spell":"remove disease"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"chill metal"},{"spell":"fog cloud"},{"spell":"heat metal"},{"spell":"lesser restoration"},{"spell":"resist energy","count":2}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"calm animals","count":2},{"spell":"cure light wounds","count":2},{"spell":"pass without trace","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"mending"},{"spell":"purify food and drink"},{"spell":"read magic"}]}],"strength":29,"dexterity":35,"constitution":39,"intelligence":18,"wisdom":22,"charisma":21,"baseatk":34,"cmb":44,"cmd":67,"feats":[{"feat":"Combat Reflexes"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Improved Critical (longbow)"},{"feat":"Improved Critical (scimitar)"},{"feat":"Improved Initiative"},{"feat":"Improved Precise Shot"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Quick Draw"},{"feat":"Rapid Shot"},{"feat":"Shot on the Run"},{"feat":"Weapon Focus (club)"},{"feat":"Weapon Focus (gore)"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Acrobatics","value":46,"special":"+50 when jumping"},{"skill":"Diplomacy","value":22},{"skill":"Disguise","value":22},{"skill":"Fly","value":10},{"skill":"Handle Animal","value":22},{"skill":"Intimidate","value":22},{"skill":"Knowledge (geography)","value":24},{"skill":"Knowledge (nature)","value":24},{"skill":"Knowledge (planes)","value":24},{"skill":"Knowledge (religion)","value":21},{"skill":"Perception","value":43},{"skill":"Ride","value":32},{"skill":"Sense Motive","value":43},{"skill":"Stealth","value":45},{"skill":"Survival","value":43},{"skill":"Swim","value":26}],"languages":["Celestial","Draconic","Infernal","Sylvan","truespeech"],"sq":[{"type":"change shape","details":"any humanoid, alter self"},{"type":"empyreal lord traits"},{"type":"perfect archer"},{"type":"seed of life"}],"environments":["any forests (Elysium)","any plains (Elysium)"],"organizations":["unique"],"treasure":"standard (+5 holy cold iron club, +5 evil outsider bane longbow)","description_visual":"This tall, graceful person has elven features, the horns of a majestic stag and a piercing, ageless stare.","group":"Empyreal Lord","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Greater Slaying Arrow","kind":"Su","details":"Cernunnos can spend 1 minute crafting any kind of greater slaying arrow (DC 32). He can have only one such arrow at a time, and it only functions for him. The save DC is Charisma-based."},{"type":"Horned Lord's Charge","kind":"Ex","details":"An opponent hit by Cernunnos's powerful charge must succeed at a DC 39 Fort save or be exhausted, sickened, or stunned (Cernunnos's choice) for 1d4 rounds. The save DC is Constitution-based."},{"type":"Lightning Rod","kind":"Su","details":"Cernunnos absorbs and negates any electricity effect that targets him or includes him in its area. As an immediate action on his next turn, he can release this energy to grant the shock weapon special ability to all weapons wielded by his allies within 30 ft. for 1 round."},{"type":"Perfect Archer","kind":"Ex","details":"Cernunnos doesn't provoke attacks of opportunity for firing bow weapons in melee. He threatens squares out to his normal reach when wielding a bow. He automatically creates arrows when firing a bow and treats any bow he wields as if it had a range increment of 500 ft."},{"type":"Primal Aura","kind":"Su","details":"Any summoned animal or creature summoned by summon nature's ally gains a +4 enhancement bonus to its Strength and Constitution while within Cernunnos's aura. Any such creature summoned within his aura obeys him as if he had summoned it (if given conflicting orders, the creature obeys Cernunnos instead of its summoner). Spells Cernunnos casts spells as 20th-level druid."},{"type":"Unbound","kind":"Su","details":"Cernunnos is immune to any effects that restrict or force extradimensional movement upon him, such as banishment or dimensional anchor. He may allow these effects to affect him."}],"description":"Cernunnos is a powerful empyreal lord who embodies the primeval force of nature as well as its wildness. He surrounds himself with counselors and advisors from all of the celestial races. Although he rarely makes a rash decision, he occasionally lets anger overwhelm his better judgment, even going so far as to swear personal vendettas against specific demon lords or archdevils. A peerless archer and hunter, in such moments of vengeance Cernunnos is tempted to visit Hell or the Abyss to personally exact his revenge. His preference for decisive action against enemies puts Cernunnos at odds with Korada. Though Cernunnos agrees that even the wickedest souls can seek redemption, he worries that lives would be lost in the time it would take to allow a fiend to seek enlightenment. The Horned Lord appears as a tall and muscular humanoid with elven features, tan skin, and a pair of antlers growing from his brow. Cernunnos dresses in simple clothes and leathers, died in natural colors but typically woven or worked with motifs of birds in flight or leaping animals. On Elysium, Cernunnos dwells in an expansive palace constructed of interwoven trees and capped with lush foliage. Known as Briarbough, this sprawling complex of gardens and pools is his seat of power and a place of healing where celestials and good mortals come to have their most grievous wounds tended. Beyond lies hundreds of miles of pristine forest and plains; animals killed here are reborn the next day, fully healed. In times of war, Briarbough serves as a headquarters and hospital for good outsiders. When not in Elysium, Cernunnos works with other celestial races to stem the spread of evil throughout the cosmos. Recognizing that-despite his power-he is still only one person, the Horned Lord uses his abilities to strengthen and bolster those already allied against darkness, training marshals and emissaries to work as his agents in the mortal and fey worlds. He favors druids and rangers-archers in particular-among his devotees. In combat, Cernunnos uses stealth and range to draw enemies to terrain of his choosing. The Empyreal Lord then uses his magic to further shape the battlefield to hamper his foes before closing for melee.\n\nCERNUNNOS'S FAITH Good fey, intelligent plant creatures, and mortal rangers and druids worship Cernunnos. Elven fighters and rogues often view him as a patron of luck and good fortune, but others pray to him for strength against evil. His sacred places are secluded groves, waterfalls, and deep forests. Cernunnos's holy symbol is the head of a stag, ram or similar horned creature with torcs or rings hanging from its horns. His favored weapon is the longbow. He grants access to the Animal, Chaos, Good, and Plant domains, and access to the Azata, Feather, Fur, and Growth subdomains.","ecology":"","habitat_society":""}];
